// Cyrus designer studio UI: the server-side SERVICE behind /api/cyrus/designer/v1. Every dependency is injected (host
// seam): the Cyrus tables through the studios' StudioStore, the build chain, the plan lookup (only for the asset chips:
// designers are NOT plan-gated), the autosave draft store. lib/cyrus/designer/studio/deps.ts wires the real ones.
//
// Model: a mod's design = the newest CyrusProjectAsset row of kind "design" for its key (rows written by a Texture /
// Sound Studio candidate build are ignored). Rows are append-only: a SAVE is a NEW revision (kind "edited", status
// "pending": nothing was built yet) plus one new asset row per changed design, after the whole mod validated and
// compiled again. The draft (one per project and person) is the autosaved working copy; it is never built or shared.
import { canonicalJson, sha256Hex } from "../../assets/textures";
import type { ManifestEntry } from "../../engine-core/revisions";
import { studioPlanView, type StudioPlanView } from "../../studios/access";
import { resolveTextures, resolveItemModels, soundCandidateIds, StudioError, textureCandidateIds, type AssetRow, type ChainInfo, type ProjectRow, type StudioServiceDeps } from "../../studios/service";
import { resolveSoundSets } from "../../studios/sound-model";
import type { DraftStore } from "../../modelstudio/service";
import { validateItemModel } from "../../itemmodel/spec";
import { DESIGN_KIND_MIME } from "../sync";
import { planDesignEdit, type EditPlan } from "../params";
import type { DesignKind } from "../gameplay/spec";
import { analyzeMod, STUDIO_LIMITS, type Analysis, type StudioCtx, type StudioLimits } from "./analyze";
import { changedIds, fileKind, isItem, type DesignFile } from "./edit";
import { itemButtons, simulateBoss, simulateItem, simulateQuests, tryMenu, type BossSimResult, type BossStep, type ItemSimResult, type ItemStep, type QuestSimResult, type QuestStep, type SimButton, type TryResult } from "./sim";

export const DRAFT_KEY = "designer";
export const MAX_FILES = 64;
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const ts = (d: Date | string) => new Date(d).getTime();

export type DesignerDeps = StudioServiceDeps & { drafts: DraftStore };

export type DesignEntry = {
  id: string; kind: DesignKind; assetId: string; origin: string; revisionId: string; seq: number | null; createdAt: string;
  history: { assetId: string; origin: string; seq: number | null; createdAt: string; label: string }[];
};
export type DesignerView = {
  project: { id: string; namespace: string; rootBuildId: string | null } | null;
  mcVersion: string; pluginName: string; headRevisionId: string | null; headSeq: number | null;
  designs: DesignEntry[]; saved: DesignFile[]; analysis: Analysis | null; limits: StudioLimits;
  /** asset chips only: what this plan may create / edit (designers themselves are not plan-gated) */
  access: StudioPlanView;
  /** the mod's asset keys the designs may reference (checked as warnings: asset_unresolved) */
  assets: { models: string[]; sounds: string[] };
  draft: { files: DesignFile[]; baseHeadId: string | null; updatedAt: string; stale: boolean } | null;
};

const LABEL: Record<string, string> = { generated: "Designed by Cyrus", edited: "Edited in the designer" };

/** Pure: the current design file per key with its history (newest first). */
export function resolveDesigns(rows: readonly AssetRow[], ignoreBuildIds: ReadonlySet<string>, seqOf: (rev: string) => number | null): { entries: DesignEntry[]; files: DesignFile[] } {
  const byKey = new Map<string, AssetRow[]>();
  for (const r of rows) if (r.kind === "design" && obj(r.provenance).spec && !ignoreBuildIds.has(String(obj(r.provenance).modBuildId ?? ""))) byKey.set(r.assetKey, [...(byKey.get(r.assetKey) ?? []), r]);
  const entries: DesignEntry[] = [];
  const files: DesignFile[] = [];
  for (const [key, list] of [...byKey].sort((a, b) => (a[0] < b[0] ? -1 : 1))) {
    list.sort((a, b) => ts(b.createdAt) - ts(a.createdAt) || (a.id < b.id ? 1 : -1));
    const cur = list[0];
    const spec = obj(cur.provenance).spec as DesignFile;
    if (!spec || spec.id !== key) continue;
    const k = fileKind(spec);
    entries.push({
      id: key, kind: (k === "other" ? "item" : k) as DesignKind, assetId: cur.id, origin: cur.origin, revisionId: cur.revisionId, seq: seqOf(cur.revisionId), createdAt: new Date(cur.createdAt).toISOString(),
      history: list.slice(0, 20).map((r) => ({ assetId: r.id, origin: r.origin, seq: seqOf(r.revisionId), createdAt: new Date(r.createdAt).toISOString(), label: LABEL[r.origin] ?? r.origin })),
    });
    files.push(spec);
  }
  return { entries, files };
}

async function ownedProject(deps: DesignerDeps, userId: string, projectId: string): Promise<ProjectRow> {
  const p = await deps.store.project(projectId);
  if (!p || p.userId !== userId) throw new StudioError(404, "not_found", "Project not found.");
  return p;
}

type Loaded = { project: ProjectRow; chain: ChainInfo; rows: AssetRow[]; entries: DesignEntry[]; files: DesignFile[]; ctx: StudioCtx; head: { id: string; seq: number; manifest: ManifestEntry[] } | null; assets: { models: string[]; sounds: string[] } };

async function load(deps: DesignerDeps, userId: string, project: ProjectRow): Promise<Loaded> {
  if (!project.rootBuildId) throw new StudioError(409, "no_build", "Build the mod once before opening the designer.");
  const chain = await deps.chain(userId, project.rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  const [rows, revs] = await Promise.all([deps.store.assets(project.id), deps.store.revisions(project.id)]);
  const seq = new Map(revs.map((r) => [r.id, r.seq]));
  const ignore = new Set([...textureCandidateIds(chain), ...soundCandidateIds(chain)]);
  const { entries, files } = resolveDesigns(rows, ignore, (id) => seq.get(id) ?? null);
  const ns = project.namespace;
  const textures = resolveTextures(rows, textureCandidateIds(chain), soundCandidateIds(chain));
  const sounds = resolveSoundSets(rows, new Map((chain.soundCandidateBuilds ?? []).map((b) => [b.id, { set: b.set, event: b.event }])), textureCandidateIds(chain));
  const itemModels = resolveItemModels(rows);
  const assets = { models: [...new Set([...textures.map((t) => `${ns}:${t.key}`), ...itemModels.map((m) => `${ns}:${m.name}`)])].sort(), sounds: sounds.flatMap((s) => s.spec.events.map((e) => `${ns}:${s.spec.name}.${e.event}`)).sort() };
  const im = Object.fromEntries(itemModels.flatMap((m) => { const v = validateItemModel(m); return v.ok ? [[`${ns}:${m.name}`, { modes: v.needs.modes, flags: v.needs.flags, use: v.needs.use }]] : []; }));
  const cfg = entries.map((e) => rows.find((r) => r.id === e.assetId)).map((r) => Number(obj(r?.provenance).configVersion)).find((n) => Number.isFinite(n) && n > 0);
  const last = revs.length ? revs[revs.length - 1] : null;
  return {
    project, chain, rows, entries, files, assets,
    ctx: { version: chain.mcVersion, namespace: ns, pluginName: chain.pluginName && /^[A-Za-z][A-Za-z0-9_]{1,39}$/.test(chain.pluginName) ? chain.pluginName : "CyrusMod", assets: { models: assets.models, sounds: assets.sounds, ...(Object.keys(im).length ? { itemModels: im } : {}) }, ...(cfg ? { configVersion: cfg } : {}) },
    head: last ? { id: last.id, seq: last.seq, manifest: last.manifest } : null,
  };
}

// ----------------------------------------------------------------------------------------------------- reads
export async function designerView(deps: DesignerDeps, userId: string, rootBuildId: string): Promise<DesignerView> {
  const chain = await deps.chain(userId, rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  const access = studioPlanView(await deps.planOf(userId).catch(() => null));
  const p = await deps.store.projectForRoot(chain.rootBuildId);
  if (!p || p.userId !== userId) return { project: null, mcVersion: chain.mcVersion, pluginName: chain.pluginName ?? "", headRevisionId: null, headSeq: null, designs: [], saved: [], analysis: null, limits: STUDIO_LIMITS, access, assets: { models: [], sounds: [] }, draft: null };
  const L = await load(deps, userId, p);
  const analysis = L.files.length ? analyzeMod(L.files, L.ctx, L.files) : null;
  const d = await deps.drafts.get(p.id, userId, DRAFT_KEY).catch(() => null);
  const doc = obj(d?.doc);
  const draftFiles = Array.isArray(doc.files) ? (doc.files as DesignFile[]).slice(0, MAX_FILES) : null;
  const draft = d && draftFiles && changedIds(L.files, draftFiles).length ? { files: draftFiles, baseHeadId: d.baseHeadId, updatedAt: new Date(d.updatedAt).toISOString(), stale: (d.baseHeadId ?? null) !== (L.head?.id ?? null) } : null;
  return { project: { id: p.id, namespace: p.namespace, rootBuildId: p.rootBuildId }, mcVersion: L.ctx.version, pluginName: L.ctx.pluginName, headRevisionId: L.head?.id ?? null, headSeq: L.head?.seq ?? null, designs: L.entries, saved: L.files, analysis, limits: STUDIO_LIMITS, access, assets: L.assets, draft };
}

/** Validate + compile the editor's working copy against the saved designs (no write). */
export async function checkDesigns(deps: DesignerDeps, userId: string, projectId: string, files: unknown): Promise<Analysis> {
  const project = await ownedProject(deps, userId, projectId);
  const L = await load(deps, userId, project);
  return analyzeMod(sameShape(L.files, files), L.ctx, L.files);
}

/** The working copy must hold the same design files as the mod (adding / removing / renaming a design is a build). */
function sameShape(saved: readonly DesignFile[], raw: unknown): DesignFile[] {
  if (!Array.isArray(raw) || raw.length > MAX_FILES) throw new StudioError(400, "bad_designs", "Send the mod's design files as a list.");
  const ids = raw.map((x) => (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string" ? (x as { id: string }).id : null));
  if (ids.some((x) => !x)) throw new StudioError(400, "bad_designs", "Every design file needs its id.");
  const want = saved.map((f) => f.id).sort().join(","), got = [...(ids as string[])].sort().join(",");
  if (want !== got) throw new StudioError(400, "design_set_changed", "Adding, removing or renaming a design needs a change build; the designer edits the designs that exist.");
  return raw as DesignFile[];
}

// ---------------------------------------------------------------------------------------------------- writes
export type SaveDesignsInput = { userId: string; projectId: string; files: unknown; expectedHeadId: string | null; message?: string | null };
export type SaveDesignsResult = { revisionId: string; seq: number; changed: string[]; configOnly: boolean; javaChanged: string[]; configVersion: number; analysis: Analysis };

export async function saveDesigns(deps: DesignerDeps, input: SaveDesignsInput): Promise<SaveDesignsResult> {
  const project = await ownedProject(deps, input.userId, input.projectId);
  const L = await load(deps, input.userId, project);
  const files = sameShape(L.files, input.files);
  const changed = changedIds(L.files, files);
  if (!changed.length) throw new StudioError(400, "no_changes", "Nothing changed since the last revision.");
  const analysis = analyzeMod(files, L.ctx, L.files);
  if (!analysis.ok || !analysis.compile.ok) {
    const n = analysis.files.reduce((s, f) => s + f.errors.length, 0) + analysis.modErrors.length || (analysis.compile.ok ? 0 : analysis.compile.errors.length);
    throw new StudioError(422, "invalid", `Fix ${n} error${n === 1 ? "" : "s"} first: the design is refused until it validates and compiles.`, { analysis });
  }
  if ((L.head?.id ?? null) !== input.expectedHeadId) throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
  const byId = new Map(files.map((f) => [f.id, f]));
  const entries = changed.map((id) => { const design = byId.get(id)!; const canonical = canonicalJson(design); return { id, design, canonical, sha: sha256Hex(canonical), path: `assets/designs/${id}.json` }; });
  const paths = new Set(entries.map((e) => e.path));
  const manifest: ManifestEntry[] = [...(L.head?.manifest ?? []).filter((e) => !paths.has(e.path)), ...entries.map((e) => ({ path: e.path, sha256: e.sha, role: "asset" as const }))];
  const diff = analysis.diff;
  const configOnly = diff?.configOnly ?? false;
  const what = changed.length === 1 ? changed[0] : `${changed.length} designs`;
  let rev: { id: string; seq: number };
  try {
    rev = await deps.store.addRevision(project.id, {
      kind: "edited", manifest, status: "pending", expectedHeadId: L.head?.id ?? null,
      engine: { toolchain: "cyrus-designer-studio 1" },
      message: (input.message ?? `Edited ${what} in the designer (${configOnly ? "config.yml only" : `${diff?.javaChanged.length ?? 0} Java files change`})`).slice(0, 200),
    });
  } catch (e) {
    if ((e as { code?: string }).code === "stale_head") throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
    throw e;
  }
  const compile = analysis.compile;
  for (const e of entries) {
    const k = fileKind(e.design);
    const base = L.entries.find((x) => x.id === e.id);
    await deps.store.recordAsset(project.id, {
      revisionId: rev.id, assetKey: e.id, kind: "design", sha256: e.sha, size: Buffer.byteLength(e.canonical), origin: "edited", mime: DESIGN_KIND_MIME[(k === "other" ? "item" : k) as DesignKind], path: e.path,
      provenance: { generator: "cyrus-designer-studio", ...(k !== "item" ? { designKind: k } : {}), spec: e.design, version: L.ctx.version, compileHash: compile.hash, configVersion: compile.configVersion, configOnly, javaChanged: diff?.javaChanged ?? [], basedOn: base?.assetId ?? null, modBuildId: null },
    });
  }
  await deps.drafts.drop(project.id, input.userId, DRAFT_KEY).catch(() => undefined);
  return { revisionId: rev.id, seq: rev.seq, changed, configOnly, javaChanged: diff?.javaChanged ?? [], configVersion: compile.configVersion, analysis };
}

// ------------------------------------------------------------------------------------------------------ draft
export async function putDraft(deps: DesignerDeps, userId: string, projectId: string, files: unknown, baseHeadId: string | null) {
  const project = await ownedProject(deps, userId, projectId);
  const L = await load(deps, userId, project);
  const f = sameShape(L.files, files);
  const bytes = Buffer.byteLength(JSON.stringify(f));
  if (bytes > 512 * 1024) throw new StudioError(413, "too_large", "This draft is too large.");
  if (!changedIds(L.files, f).length) { await deps.drafts.drop(project.id, userId, DRAFT_KEY); return { saved: false as const }; }
  const r = await deps.drafts.put({ projectId: project.id, ownerRef: userId, assetKey: DRAFT_KEY, baseAssetId: null, baseHeadId, doc: { v: 1, files: f } });
  return { saved: true as const, updatedAt: new Date(r.updatedAt).toISOString() };
}
export async function dropDraft(deps: DesignerDeps, userId: string, projectId: string) {
  const project = await ownedProject(deps, userId, projectId);
  await deps.drafts.drop(project.id, userId, DRAFT_KEY);
}

// ------------------------------------------------------------------------------------------- simulate / plan
export async function simulate(deps: DesignerDeps, userId: string, projectId: string, body: { files: unknown; mode: "item"; item: string; steps: ItemStep[] } | { files: unknown; mode: "menu"; menu: string; clicks: number[] } | { files: unknown; mode: "quests"; steps: QuestStep[] } | { files: unknown; mode: "boss"; boss: string; steps: BossStep[] }):
  Promise<{ mode: "item"; result: ItemSimResult; buttons: SimButton[] } | { mode: "menu"; result: TryResult } | { mode: "quests"; result: QuestSimResult } | { mode: "boss"; result: BossSimResult }> {
  const project = await ownedProject(deps, userId, projectId);
  const L = await load(deps, userId, project);
  const files = sameShape(L.files, body.files);
  // the simulators need well-formed designs: run them on the working copy only when it validates
  const a = analyzeMod(files, L.ctx);
  const bad = a.files.filter((f) => !f.ok).map((f) => f.id);
  if (bad.length) throw new StudioError(422, "invalid", `The simulator runs valid designs only. Fix ${bad.join(", ")} first.`);
  try {
    if (body.mode === "item") { const d = files.find((f) => f.id === body.item); if (!d || !isItem(d)) throw new StudioError(404, "not_found", `No item ${body.item}.`); return { mode: "item", result: simulateItem(files, body.item, body.steps, project.namespace), buttons: itemButtons(d) }; }
    if (body.mode === "menu") return { mode: "menu", result: tryMenu(files, body.menu, body.clicks, project.namespace) };
    if (body.mode === "boss") return { mode: "boss", result: simulateBoss(files, body.boss, body.steps, project.namespace) };
    return { mode: "quests", result: simulateQuests(files, body.steps, project.namespace) };
  } catch (e) {
    if (e instanceof StudioError) throw e;
    throw new StudioError(422, "sim_failed", `The simulator stopped: ${(e as Error).message.slice(0, 160)}`);
  }
}

/** The dock: a settings-only request is recognised without a model (planDesignEdit). Nothing is sent anywhere. */
export async function planEdit(deps: DesignerDeps, userId: string, projectId: string, text: string, files: unknown): Promise<EditPlan> {
  const project = await ownedProject(deps, userId, projectId);
  const L = await load(deps, userId, project);
  const f = sameShape(L.files, files);
  const items = f.filter(isItem);
  if (!items.length) return { kind: "model", reason: "no item designs" };
  try { return planDesignEdit(String(text).slice(0, 400), items); } catch { return { kind: "model", reason: "could not read the request" }; }
}
// Cyrus designer studio UI: the REAL dependencies of /api/cyrus/designer/v1 and the designer pages. SERVER ONLY.
// No new Nxeon imports: everything comes through the studios' existing wiring (lib/cyrus/studios/deps.ts: the Cyrus
// access rule, the studios setting cyrus_studios_enabled, the plan lookup, the store) and the host seam (rate limit).
// Visible only when the studios are visible to the viewer AND CYRUS_DESIGNER=1 (the designer switch, default off).
import { getHost } from "../../host";
import { serviceDeps, studioPlanOf, studioViewer } from "../../studios/deps";
import { prismaModelDraftStore } from "../../studios/store-prisma";
import { StudioError } from "../../studios/service";
import type { StudioViewer } from "../../studios/http";
import { memoryDraftStore, type DraftStore } from "../../modelstudio/service";
import { designerOn } from "../route";
import type { DesignerApiDeps } from "./http";
import type { DesignerDeps } from "./service";

/** Fails closed: the designer switch off (or unreadable) hides the designer pages and APIs. */
export const designerStudioOn = (env: Record<string, string | undefined> = process.env) => designerOn(env);

/** Who may see the designer now: the studios viewer AND the designer switch. */
export async function designerViewer(env: Record<string, string | undefined> = process.env): Promise<(StudioViewer & { user: unknown }) | null> {
  if (!designerStudioOn(env)) return null;
  return studioViewer().catch(() => null);
}

/** Drafts that never take a request down: a missing table (schema not pushed yet) answers 503, not 500. */
function safeDrafts(inner: DraftStore): DraftStore {
  const wrap = <A extends unknown[], R>(f: (...a: A) => Promise<R>) => async (...a: A): Promise<R> => {
    try { return await f(...a); } catch (e) { console.error("[cyrus-designer] drafts:", (e as Error).message); throw new StudioError(503, "drafts_unavailable", "Autosave is not available right now; your edits stay in this tab until you save a revision."); }
  };
  return { get: wrap(inner.get), put: wrap(inner.put), drop: wrap(inner.drop) };
}

const G = globalThis as { __cyrusDesignerDrafts?: DraftStore };
export function designerServiceDeps(env: Record<string, string | undefined> = process.env): DesignerDeps {
  // devhost / tests only: CYRUS_DESIGNER_DRAFTS=memory keeps drafts in the process (no table needed)
  const drafts = env.CYRUS_DESIGNER_DRAFTS === "memory" && env.NODE_ENV !== "production" ? (G.__cyrusDesignerDrafts ??= memoryDraftStore()) : safeDrafts(prismaModelDraftStore);
  return { ...serviceDeps(env), planOf: studioPlanOf(env), drafts };
}

export function designerApiDeps(env: Record<string, string | undefined> = process.env): DesignerApiDeps {
  return {
    viewer: () => designerViewer(env),
    service: designerServiceDeps(env),
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(`cyrus:${key}`, { max, windowMs }),
  };
}

// Creating a mod build (the AI Mod Builder / Cyrus): validation, rate limits, the Cyrus token
// gate, the DB row, attachments and the hand-off to the build service. Shared by
// POST /api/mod-builder/builds and the Cyrus forge stream (POST /api/cyrus/generate), so both
// enforce exactly the same rules. Server only.
import { promptProblem } from "../cyrus/prompt-check";
import { randomBytes } from "node:crypto";
import type { User } from "@prisma/client";
import { db } from "@/lib/db";
import { svcCreate, svcHealthCached, ModBuilderUnavailable } from "@/lib/modbuilder/client";
import { toView } from "@/lib/modbuilder/store";
import { MB_VERSIONS, type ModBuildView } from "@/lib/modbuilder/types";
import { checkRateLimit } from "@/lib/rate-limit";
import { isCyrusModel } from "@/lib/cyrus/models";
import { readCyrusMeta, type CyrusMeta } from "@/lib/cyrus/meta";
import { claimUploads, isUploadId, readAttachment } from "@/lib/cyrus/uploads";
import type { CyrusAttachment } from "@/lib/cyrus/meta";
import { gateBuild, releaseBuildTokens } from "@/lib/cyrus/tokens/builds";
import { serviceBuildId } from "@/lib/cyrus-mods/registry";
import { cyrusSuspension } from "@/lib/cyrus/suspensions";
import { cyrusGameBuildable } from "@/lib/cyrus/game-status.server";
import { existingAssetKinds, resolveBuildAssets, type AssetRequestDeps } from "@/lib/cyrus/assets/request";
import { hasDatapacks, hasWorldgenDatapacks } from "@/lib/cyrus/datapack/route";
import { hasBossDesigns, hasDesigns, hasGameplayDesigns, hasHudDesigns, hasMotionDesigns } from "@/lib/cyrus/designer/route";
import { hasItemModels } from "@/lib/cyrus/itemmodel/route";
import { tierOf } from "@/lib/cyrus/tokens/access";
import { createProject, projectForRootBuild } from "@/lib/cyrus/engine-core/store";
import { catalogOfferForBuild } from "@/lib/cyrus/library/v2/build-wiring";

/** The real lookups behind the asset gate (plan tier from the token economy, the engine-core project store). */
export const assetRequestDeps: AssetRequestDeps = {
  tierOf: (userId) => tierOf(userId),
  projectForRootBuild: async (rootBuildId) => projectForRootBuild(rootBuildId),
  createProject: async (i) => createProject(i),
};

const MAX_INFLIGHT = 2;

export type CreateBuildResult =
  | { ok: true; status: 201; build: ModBuildView; reserved: number | null; assetNotices?: string[] }
  | { ok: false; status: number; json: Record<string, unknown> };

const fail = (status: number, json: Record<string, unknown>): CreateBuildResult => ({ ok: false, status, json });

/** `body` is the JSON the API takes: { prompt, mcVersion, changeRequest, baseBuildId, model, attachmentIds, retarget?, assets? }.
 *  `assets` (Cyrus R1) is only a REQUEST (["texture"] / { texture: true }); the plan gate decides. */
export async function createModBuild(user: User, body: Record<string, unknown>): Promise<CreateBuildResult> {
  const prompt = String(body.prompt ?? "").trim();
  const mcVersion = String(body.mcVersion ?? MB_VERSIONS[0]);
  const changeRequest = body.changeRequest ? String(body.changeRequest).trim() : "";
  const baseBuildId = body.baseBuildId ? String(body.baseBuildId) : null;
  // Cyrus (optional, additive): the model picked in the composer and pasted images.
  if (body.model !== undefined && !isCyrusModel(body.model)) return fail(400, { error: "Pick Katara, Saka or Yakko." });
  const attachmentIds = Array.isArray(body.attachmentIds) ? body.attachmentIds.filter(isUploadId).slice(0, 4) : [];

  if (!(MB_VERSIONS as readonly string[]).includes(mcVersion)) return fail(400, { error: "Pick a Minecraft version from the list." });

  let base = null;
  if (baseBuildId) {
    base = await db.modBuild.findUnique({ where: { id: baseBuildId } });
    if (!base || base.userId !== user.id) return fail(404, { error: "Not found" });
    if (base.status !== "succeeded") return fail(400, { error: "You can only change a build that finished." });
    if (changeRequest.length < 4 || changeRequest.length > 2000) return fail(400, { error: "Describe the change in a few words (up to 2,000 characters)." });
  } else if (prompt.length < 12 || prompt.length > 4000) {
    return fail(400, { error: prompt.length < 12 ? "Tell us a bit more about what the plugin should do." : "That's a lot! Keep it under 4,000 characters." });
  }

  // Not a mod request (gibberish, "Yo Yo Yo", repetition, only symbols): refuse BEFORE tokens are held or the
  // AI is called. Free, instant, and never charged (lib/cyrus/prompt-check.ts).
  const unclear = promptProblem(base ? changeRequest : prompt);
  if (unclear) return fail(400, { error: unclear, code: "prompt_unclear" });

  // Cyrus admin (/admin/cyrus): an account suspended from building, or Minecraft switched off.
  if (await cyrusSuspension(user.id, "build")) return fail(403, { error: "Cyrus building is paused on this account. Contact support if you think this is a mistake.", code: "suspended" });
