        assetState.assetRepairs += 1;
      } else if (pre.length) {
        for (const h of pre) precheckSeen.set(preKey(h), (precheckSeen.get(preKey(h)) || 0) + 1);
        rec.precheck = [...(rec.precheck || []), ...pre.map((h) => ({ rule: h.rule, where: h.where, attempt: rec.attempts }))].slice(-40);
        problem = { kind: "compile", count: pre.length, text: pre.map((h) => `- ${h.where}: ${h.message}\n    ${h.evidence}`).join("\n"), say: `Pre-check found ${pre.length} known API mistake${pre.length > 1 ? "s" : ""}` };
      } else {
        setStage(rec, rec.attempts > 1 ? "repairing" : "compiling", `Compiling against Paper ${rec.mcVersion}${rec.attempts > 1 ? ` (attempt ${rec.attempts})` : ""}`);
        let c = await timedCompile(ws, rec, ctl);
        // Mechanical compile errors (wrong import package, missing API import, renamed constant

        // Mechanical compile errors (wrong import package, missing API import, renamed constant
        // with exactly one right name in this version's jar) are fixed here, then recompiled,
        // before any model repair is spent. At most 2 rounds.
        for (let k = 0; !c.ok && AUTOFIX && k < 2 && !ctl.cancelled; k++) {
          t0 = Date.now();
          let fx = { fixes: [] };
          try { fx = AF.fixCompile(c.errors, ws, rec.mcVersion, { classIndex, members }); } catch (e) { log("warn", "autofix failed", { id: rec.id, err: String(e) }); }
          U.addTime(rec, "autofix", Date.now() - t0);
          if (!fx.fixes.length) break;
          roundFixes.push(...fx.fixes);
          event(rec, rec.status, `Fixed ${fx.fixes.length} known API mistake${fx.fixes.length > 1 ? "s" : ""} automatically`);
          c = await timedCompile(ws, rec, ctl);
        }
        recordFixes(c.ok);
        if (ctl.cancelled) throw fail(ctl.timeout ? "timeout" : "cancelled", ctl.timeout ? "This build ran out of time." : "Build cancelled.");
        if (!c.ok) {
          const count = (c.errors.match(/^\d+ errors?$/m) || ["compile errors"])[0];
          const hints = apiHints(c.errors, ws, rec.mcVersion);
          problem = { kind: "compile", count: parseInt(count, 10) || 99, hints, text: hints ? `${c.errors.slice(0, 8000 - Math.min(hints.length, 3000))}${hints.slice(0, 3000)}` : c.errors, say: `Compiler found ${count}` };
        } else if (warningCheck(c.warnings, rec.mcVersion).filter((h) => !precheckSeen.has(preKey(h))).length) {
          const wh = warningCheck(c.warnings, rec.mcVersion).filter((h) => !precheckSeen.has(preKey(h)));
          for (const h of wh) precheckSeen.set(preKey(h), 1);
          rec.precheck = [...(rec.precheck || []), ...wh.map((h) => ({ rule: h.rule, where: h.where, attempt: rec.attempts }))].slice(-40);
          problem = { kind: "compile", count: wh.length, text: wh.map((h) => `- ${h.message}\n    ${h.evidence}`).join("\n"), say: `Found ${wh.length} known runtime problem${wh.length > 1 ? "s" : ""}` };
        } else {
          event(rec, rec.status, "Compiled successfully");
          setStage(rec, "scanning", "Running the safety check");
          t0 = Date.now();
          const findings = scanFindings(ws, c, rec);
          U.addTime(rec, "scan", Date.now() - t0);
          const blocks = findings.filter((f) => f.severity === "block");
          if (blocks.length) {
            if (safetyRepairs >= 1 || repairs >= MAX_REPAIRS) {
              rec.safety = { verdict: "block", findings };
              throw fail("safety", `The plugin was blocked by our safety check: it ${blocks[0].message}. Try rewording the request without that part.`, blocks.map((b) => `${b.rule} ${b.where}: ${b.evidence}`).join("\n"));
            }
            safetyRepairs += 1;
            problem = { kind: "safety", text: blocks.map((b) => `- ${b.where}: ${b.message} (${b.evidence})`).join("\n"), say: `Safety check flagged ${blocks.length} thing${blocks.length > 1 ? "s" : ""}` };
          } else {
            const warns = findings.filter((f) => f.severity === "warn");
            if (rec.scanProfile === "attested") {
              // Imported code: never "passed" or "safe", only what the attested profile found.
              rec.safety = { verdict: "warn", profile: "attested", summary: attestedSummary(findings), findings };
              event(rec, "scanning", attestedSummary(findings));
            } else {
              rec.safety = { verdict: warns.length ? "warn" : "pass", findings };
              event(rec, "scanning", warns.length ? `Safety check passed with ${warns.length} note${warns.length > 1 ? "s" : ""}` : "Safety check passed: no network, no commands outside the game, own folder only");
            }
            await finish(rec, ws, c, v.yml);
            return;
          }
        }
      }
      // ---- repair loop
      recordFixes(false);
      lastErr = problem.text;
      if (repairs >= MAX_REPAIRS) throw fail("compile", `We couldn't get this plugin to build after ${rec.attempts} tries. Try a simpler description, or split it into smaller plugins.`, lastErr);
      if (rec.costUsd >= BUILD_BUDGET_USD) throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request.", lastErr);
      repairs += 1;
      rec.repairs = repairs;
      // Repair ladder: a small compile problem first goes to the cheap model; a
      // repair that did not work escalates (cheap -> generation model -> one class up).
      const rm = rec.route.models;
      const small = problem.kind === "compile" && (problem.count || 99) <= R.CFG.repairSmallMax;
      if (rec.override) nextModel = repairs <= (rm.escalateAfter || 2) ? rm.generate : rm.escalate;
      else if (!R.CFG.routing) nextModel = REPAIR_MODEL;
      else if (repairs === 1) nextModel = small && rm.repairCheap ? rm.repairCheap : rm.generate;
      else if (usedModel === rm.repairCheap && rm.repairCheap !== rm.generate) nextModel = rm.generate;
      else nextModel = rm.escalate;
      nextKind = problem.kind === "safety" ? "repair-safety" : problem.kind === "asset" || problem.kind === "design" ? "repair-asset" : "repair";
      if (problem.kind === "safety") nextModel = R.CFG.routing || rec.override ? rm.generate : REPAIR_MODEL;
      setStage(rec, "repairing", `${problem.say}. Fixing it automatically (fix ${repairs} of ${MAX_REPAIRS})`);
      event(rec, "repairing", "Error details", problem.text.slice(0, 3000));
      if (problem.hints) event(rec, "repairing", "API lookup", problem.hints);
      rec.repairPlan = [...(rec.repairPlan || []), { repair: repairs, model: nextModel, small, kind: problem.kind }];
      prompt = P.repairPrompt(problem.kind, problem.text.slice(0, 8000), ws, AF.fixNote(roundFixes));
    }
  } catch (e) {
    rec.status = "failed";
    rec.errorCode = ctl.timeout ? "timeout" : (e.code || "internal");
    rec.error = ctl.timeout ? "This build ran out of time. Try a smaller request." : (e.code ? e.message : "Something went wrong on our side. Please try again.");
    rec.errorDetail = e.detail ? String(e.detail).slice(0, 8000) : (e.code ? undefined : String(e.stack || e).slice(0, 2000));
    if (!e.code) log("error", "build crashed", { id: rec.id, err: String(e.stack || e) });
    rec.events.push({ at: now(), stage: "failed", message: rec.error });
    rec.files = srcList(ws);
  } finally {
    clearTimeout(killer);
    keptSpecs.delete(rec.id);
    try {
      rmrf(finalWs);
      if (fs.existsSync(ws)) { copyDir(ws, finalWs, (s, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s) === ws)); rmrf(ws); }
    } catch (e) { log("error", "workspace persist failed", { id: rec.id, err: String(e) }); }
    rec.durationMs = Date.now() - started;
    rec.finishedAt = rec.finishedAt || now();
    running.delete(rec.id);
    save(rec);
    if (rec.status === "succeeded" && rec.dedupeKey && !rec.reusedFrom) dedupeIndex.set(rec.dedupeKey, rec.id);
    log("info", "build finished", { id: rec.id, status: rec.status, attempts: rec.attempts, costUsd: rec.costUsd, durationMs: rec.durationMs, usage: usageLine(rec) });
    pump();
  }
}

// ------------------------------------------------------------- Cyrus import ----
async function runImport(rec) {
  const ctl = { child: null, cancelled: false };
  running.set(rec.id, ctl);
  const started = Date.now();
  rec.startedAt = now();
  const ws = path.join(WORK, rec.id);
  const finalWs = path.join(dirOf(rec.id), "ws");
  const payload = path.join(dirOf(rec.id), "import");
  try {
    rmrf(ws);
    if (rec.importKind === "jar") {
      setStage(rec, "scanning", "Analysing the imported jar with the attested profile (it is never run)");
      const t0 = Date.now();
      const findings = scanBytecode(path.join(payload, "classes"), { profile: "attested" });
      U.addTime(rec, "scan", Date.now() - t0);
      const blocks = findings.filter((f) => f.severity === "block");
      rec.safety = { verdict: blocks.length ? "block" : "warn", profile: "attested", summary: attestedSummary(findings), findings };
      rec.analysisOnly = true;
      rec.warnings = [`${attestedSummary(findings)}${blocks.length ? `, ${blocks.length} block${blocks.length > 1 ? "s" : ""}` : ""}. Jar-only import: analysis and diagnosis only; Cyrus cannot change it.`,
        ...findings.filter((f) => f.severity !== "pass").slice(0, 40).map((f) => `${f.severity === "block" ? "Blocked" : "Warning"}: it ${f.message} (${f.where}).`)];
      rec.status = "succeeded";
      rec.finishedAt = now();
      rec.events.push({ at: now(), stage: "succeeded", message: "Analysis ready" });
      return;
    }
    fs.mkdirSync(ws, { recursive: true });
    for (const g of ["build.gradle.kts", "settings.gradle.kts"]) fs.copyFileSync(path.join(TEMPLATE, g), path.join(ws, g));
    copyDir(path.join(payload, "src"), path.join(ws, "src"));
    setStage(rec, "compiling", "Checking the imported files");
    sanitizeWorkspace(ws, rec);
    const secretHits = scanSecrets(listFiles(ws), [...SECRETS, ...credentialSecrets()]);
    if (secretHits.length) { rmrf(ws); throw fail("safety", "The imported files were blocked by our safety checks.", "secret-scan"); }
    rec.attempts = 1;
    const v = validate(ws, rec);
    if (v.problems.length) throw fail("compile", `Cyrus can't build this import yet: ${v.problems[0]}`, v.problems.join("\n"));
    setStage(rec, "compiling", `Compiling your source against Paper ${rec.mcVersion}${(rec.importDeps || []).length ? ` with ${rec.importDeps.length} allowlisted dependenc${rec.importDeps.length > 1 ? "ies" : "y"}` : ""}`);
    const c = await timedCompile(ws, rec, ctl);
    if (ctl.cancelled) throw fail("cancelled", "Import cancelled.");
    if (!c.ok) throw fail("compile", `Your source did not compile against Paper ${rec.mcVersion} with Cyrus's dependency allowlist. Fix the errors (or ask Cyrus to after importing a version that compiles) and import it again.`, c.errors);
    event(rec, "compiling", "Compiled successfully");
    setStage(rec, "scanning", "Checking it with the attested profile");
    const t0 = Date.now();
    const findings = scanFindings(ws, c, rec);
    U.addTime(rec, "scan", Date.now() - t0);
    const blocks = findings.filter((f) => f.severity === "block");
    if (blocks.length) {
      rec.safety = { verdict: "block", profile: "attested", summary: attestedSummary(findings), findings };
      throw fail("safety", `Cyrus can't build this import: it ${blocks[0].message} (${blocks[0].where}). That stays blocked even for code you own.`, blocks.map((b) => `${b.rule} ${b.where}: ${b.evidence}`).join("\n"));
    }
    rec.attestedBaseline = baselineOf(findings);
    rec.safety = { verdict: "warn", profile: "attested", summary: attestedSummary(findings), findings };
    event(rec, "scanning", attestedSummary(findings));
    await finish(rec, ws, c, v.yml);
  } catch (e) {
    rec.status = "failed";
    rec.errorCode = e.code || "internal";
    rec.error = e.code ? e.message : "Something went wrong on our side. Please try again.";
    rec.errorDetail = e.detail ? String(e.detail).slice(0, 8000) : (e.code ? undefined : String(e.stack || e).slice(0, 2000));
    if (!e.code) log("error", "import crashed", { id: rec.id, err: String(e.stack || e) });
    rec.events.push({ at: now(), stage: "failed", message: rec.error });
    rec.files = srcList(ws);
  } finally {
    try {
      rmrf(finalWs);
      if (fs.existsSync(ws)) { copyDir(ws, finalWs, (s2, e2) => !(e2.isDirectory() && e2.name === "build" && path.dirname(s2) === ws)); rmrf(ws); }
    } catch (e) { log("error", "workspace persist failed", { id: rec.id, err: String(e) }); }
    rec.durationMs = Date.now() - started;
    rec.finishedAt = rec.finishedAt || now();
    running.delete(rec.id);
    save(rec);
    log("info", "import finished", { id: rec.id, kind: rec.importKind, status: rec.status, durationMs: rec.durationMs });
    pump();
  }
}

async function timedCompile(ws, rec, ctl) {
  const t0 = Date.now();
  try { return await compile(ws, rec, ctl); } finally { U.addTime(rec, "compile", Date.now() - t0); }
}

// One structured line per build for `docker logs` (the full detail is in build.json).

function designRound(ws, rec, st, repairs) {
  if (!dsOn(rec)) return null;
  const ctx = { namespace: rec.assets.namespace, mcVersion: rec.mcVersion };
  let dz = DZS.checkWorkspaceDesigns(ws, ctx);
  const canRepair = st.assetRepairs < MAX_ASSET_REPAIRS && repairs < MAX_REPAIRS;
  if (!dz.files.length) {
    if (canRepair) return { kind: "design", count: 1, text: `- No design was written. Write at least one design at assets/designs/<id>.json (see ITEM DESIGNER${gpOn(rec) ? " and MENUS AND QUESTS" : ""}${bsOn(rec) ? " and BOSSES AND ENCOUNTERS" : ""}${hdOn(rec) ? " and HUD AND GLYPHS" : ""}${mtOn(rec) ? " and MOTION PROPS" : ""}).`, say: "No design found" };
    throw fail("compile", "Cyrus could not design this item. Try describing the item and its abilities more simply.", "no designs");
  }
  if (dz.problems.length && canRepair) return { kind: "design", count: dz.problems.length, text: dz.problems.map((p) => `- ${p}`).join("\n"), say: `Design check found ${dz.problems.length} problem${dz.problems.length > 1 ? "s" : ""}` };
  const droppedWhy = [];
  for (let round = 0; round < DZS.MAX_DESIGN_FILES + 1 && dz.results.some((r) => !r.ok); round++) {
    for (const r of dz.results.filter((x) => !x.ok)) {
      droppedWhy.push(...r.problems);
      fs.rmSync(path.join(ws, r.rel), { force: true });
      rec.assetDowngrades = [...(rec.assetDowngrades || []), { name: r.name, kind: "design", ...(r.kind && r.kind !== "item" ? { designKind: r.kind } : {}), reason: r.problems[0] || "failed the design checks" }].slice(-32);
      event(rec, rec.status, `Dropped the ${r.kind && r.kind !== "item" ? r.kind : "item"} design ${r.name}: it did not pass the design checks`);
    }
    for (const f of dz.files.slice(DZS.MAX_DESIGN_FILES)) fs.rmSync(f.abs, { force: true });
    dz = DZS.checkWorkspaceDesigns(ws, ctx);
  }
  const ok = dz.results.filter((r) => r.ok);
  if (!ok.length) throw fail("compile", "None of the item designs passed Nxeon's design checks, so there is nothing to build. Try a simpler description.", [...droppedWhy, ...dz.problems].slice(0, 12).join("\n"));
  const c = DZS.compileWorkspaceDesigns(ws, rec, ok.map((r) => r.spec));
  if (!c.ok) {
    if (canRepair) return { kind: "design", count: c.errors.length, text: c.errors.map((p) => `- ${p}`).join("\n"), say: "The designs could not be compiled" };
    throw fail("compile", "The item designs could not be turned into a plugin.", c.errors.join("\n"));
  }
  rec.designCompile = c.summary;
  rec.designResults = ok.map((r) => ({ name: r.name, path: r.rel, sha256: r.sha256, spec: r.spec, warnings: r.warnings, budgets: r.budgets, ...(r.kind && r.kind !== "item" ? { kind: r.kind } : {}) }));
  const cnt = c.summary.counts;
  event(rec, rec.status, cnt && cnt.huds ? `Compiled ${cnt.items} item, ${cnt.menus} menu, ${cnt.quests} quest, ${cnt.bosses || 0} boss, ${cnt.encounters || 0} encounter and ${cnt.huds} HUD design${ok.length > 1 ? "s" : ""} into the plugin (${c.summary.files.length} files, ${c.summary.params.length} settings in config.yml)` : cnt && (cnt.bosses || cnt.encounters) ? `Compiled ${cnt.items} item, ${cnt.menus} menu, ${cnt.quests} quest, ${cnt.bosses} boss and ${cnt.encounters} encounter design${ok.length > 1 ? "s" : ""} into the plugin (${c.summary.files.length} files, ${c.summary.params.length} settings in config.yml)` : cnt && (cnt.menus || cnt.quests) ? `Compiled ${cnt.items} item, ${cnt.menus} menu and ${cnt.quests} quest design${ok.length > 1 ? "s" : ""} into the plugin (${c.summary.files.length} files, ${c.summary.params.length} settings in config.yml)` : `Compiled ${ok.length} item design${ok.length > 1 ? "s" : ""} into the plugin (${c.summary.files.length} files, ${c.summary.params.length} settings in config.yml)`);
  return null;
}

// One asset round (only when textures or sounds are allowed): HARD problems go back to the model (bounded by
// MAX_ASSET_REPAIRS and the overall repair cap), soft ones once; when the repairs are used up, specs that still fail
// are DROPPED with a customer-visible reason (downgrade), never shipped. Returns a repair problem or null.
async function compile(ws, rec, ctl) {
  const out = path.join(ws, "build/classes");
  rmrf(path.join(ws, "build")); fs.mkdirSync(out, { recursive: true });
  const paperCp = fs.readFileSync(path.join(CP_DIR, `${rec.mcVersion}.txt`), "utf8").trim();
  // Cyrus import: the allowlisted compile-only jars (sha256-verified on every compile; never shaded into the jar).
  let depJars = [];
  try { depJars = IMP.depClasspath([...new Set([...(rec.importDeps || []), ...(creOn(rec) ? CR.CREATURE_DEPS : []), ...(dsOn(rec) && rec.designCompile && Array.isArray(rec.designCompile.deps) ? rec.designCompile.deps : [])])]); } catch (e) { throw fail("unavailable", "A dependency this plugin needs is not available on the builder right now.", e.message); }
  const cp = depJars.length ? `${paperCp}:${depJars.join(":")}` : paperCp;
  const sources = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")).map((f) => f.abs);
  const tc = javacFor(rec.mcVersion);
  const r = await run(tc.javac, ["-J-Xmx768m", "--release", tc.release, "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", out, ...sources],
    { cwd: ws, env: childEnv(false), timeout: 180000, track: ctl });
  ctl.child = null;
  const output = (r.err + r.out).split(ws + "/").join("");
  if (r.code !== 0) return { ok: false, errors: output.slice(0, 12000) };
  // Resources (plugin.yml, config.yml, ...)
  copyDir(path.join(ws, "src/main/resources"), out);
  const jar = path.join(ws, "build/plugin.jar");
  // Reproducible jar: sorted entries + a fixed entry timestamp (JDK 19+ `--date`), so the same source gives the same bytes.
  // If this JDK rejects --date, fall back to the old unsorted form rather than failing the build.
  const rel = (f) => f.rel.slice("build/classes/".length);
  const entries = jarEntries(listFiles(ws, "build/classes").map(rel));
  let j = await run("jar", jarArgs(jar, out, entries), { cwd: ws, env: childEnv(false), timeout: 60000 });
  if (j.code !== 0 && /--date|illegal option|unrecognized option|usage/i.test(j.err + j.out)) {
    j = await run("jar", ["--create", "--file", jar, "-C", out, "."], { cwd: ws, env: childEnv(false), timeout: 60000 });
  }
  if (j.code !== 0) return { ok: false, errors: j.err.slice(0, 4000) };
  const warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 10);
  return { ok: true, jar, classes: out, warnings };
}

// ------------------------------------------------------------ pipeline ----
function buildRelease(rec) {
  const depIds = [...new Set([...(rec.importDeps || []), ...(creOn(rec) ? CR.CREATURE_DEPS : [])])];
  const m = IMP.loadDepsManifest();
  const deps = depIds.map((id) => { const d = (m.dependencies || []).find((x) => x.id === id); return { id, sha256: d && d.sha256 ? String(d.sha256) : null }; });
  const ar = rec.assetResult || {};
  return REL.releaseFor(rec, {
    rulesVersion: P.knowledgeVersion().split("+")[1] || null, registryFile: REGISTRY_FILE, cpDir: CP_DIR, tc: javacFor(rec.mcVersion), deps,
    sections: { assets: ar.promptVersion, datapack: ar.datapackPromptVersion, design: ar.designPromptVersion, itemmodel: ar.itemModelPromptVersion },
    sheetsOn: process.env.MB_SHEETS !== "off", depsManifestVersion: m.version || null,
  });
}

async function finish(rec, ws, c, yml) {
  const s = readSummary(ws) || {};
  const name = String(yml.name);
  const version = String(yml.version);
  const jarName = `${name}-${version}.jar`;
  const dest = path.join(dirOf(rec.id), "artifact.jar");
  fs.copyFileSync(c.jar, dest);
  const buf = fs.readFileSync(dest);
  rec.jar = { name: jarName, size: buf.length, sha256: crypto.createHash("sha256").update(buf).digest("hex") };
  rec.pluginName = name;
  rec.version = version;
  const arr = (x) => (Array.isArray(x) ? x : []);
  const ymlCommands = yml.commands && typeof yml.commands === "object" ? yml.commands : {};
  const ymlPerms = yml.permissions && typeof yml.permissions === "object" ? yml.permissions : {};
  rec.summary = {
    tagline: str(s.tagline, 200) || String(yml.description || "").slice(0, 200),
    text: str(s.summary, 1500),
    howToUse: arr(s.howToUse).map((x) => str(x, 300)).filter(Boolean).slice(0, 12),
    limitations: arr(s.limitations).map((x) => str(x, 300)).filter(Boolean).slice(0, 8),
    changes: str(s.changes, 600),
  };
  rec.commands = arr(s.commands).length
    ? arr(s.commands).slice(0, 40).map((x) => ({ usage: str(x.usage, 120), description: str(x.description, 300), permission: str(x.permission, 120), whoCanUse: str(x.whoCanUse, 60) }))
    : Object.entries(ymlCommands).map(([k, v]) => ({ usage: (v && v.usage) ? String(v.usage).replace("<command>", k) : `/${k}`, description: str(v && v.description, 300), permission: str(v && v.permission, 120), whoCanUse: "" }));
  rec.permissions = arr(s.permissions).length
    ? arr(s.permissions).slice(0, 60).map((x) => ({ node: str(x.node, 120), description: str(x.description, 300), default: str(x.default, 10) }))
    : Object.entries(ymlPerms).map(([k, v]) => ({ node: k, description: str(v && v.description, 300), default: String((v && v.default) ?? "op") }));
  rec.config = arr(s.config).slice(0, 60).map((x) => ({ key: str(x.key, 120), description: str(x.description, 300), default: str(typeof x.default === "object" ? JSON.stringify(x.default) : x.default, 200) }));
  rec.warnings = [
    ...(rec.safety && rec.safety.profile === "attested" ? [`${rec.safety.summary}. This is imported code: Nxeon checked it but does not guarantee that it is safe.`] : []),
    ...c.warnings.map((w) => w.replace(/^warning: /, "Compiler: ")),
    ...(rec.safety ? rec.safety.findings.filter((f) => f.severity === "warn").map((f) => `This plugin ${f.message} (${f.where}).`) : []),
  ];
  // Cyrus R1: the texture specs that ship with this jar (the portal renders, hosts and installs the pack).
  const ar = assetResultOf(ws, rec);
  if (ar) {
    rec.assetResult = ar;
    rec.warnings.push(...ar.warnings);
