// Server half of the Cyrus studio pages (/dashboard/cyrus/<buildId>/studio/{texture,sound,plans}).
// Gates, in order: the Cyrus access rule (requireModBuilderUser: preview, or the public launch) -> the studios
// visibility (cyrus_studios_enabled OR a preview account; else 404 like any missing page) -> ownership of the build.
// The plan decision is the API's (every request is checked again server side); the page only uses it to redirect
// /studio/texture to the locked state. No studio data is read here: the client loads it from /api/cyrus/assets/v1.
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireModBuilderUser } from "@/lib/modbuilder/access";
import { readCyrusMeta } from "@/lib/cyrus/meta";
import { CATEGORY_BY_KEY } from "@/lib/cyrus/data";
import { toCategory } from "@/lib/cyrus/categories";
import { studioPlanView } from "@/lib/cyrus/studios/access";
import { studioPlanOf, studioViewer } from "@/lib/cyrus/studios/deps";
import type { StudioMod } from "@/components/cyrus/studios/StudioShell";

export async function studioContext(buildId: string) {
  const user = await requireModBuilderUser();
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(buildId)) notFound();
  const viewer = await studioViewer();
  if (!viewer || viewer.userId !== user.id) notFound();
  const build = await db.modBuild.findUnique({ where: { id: buildId }, select: { id: true, userId: true, rootBuildId: true, pluginName: true, cyrus: true } });
  if (!build || build.userId !== user.id) notFound();
  const root = build.rootBuildId ?? build.id;
  const chain = await db.modBuild.findMany({ where: { userId: user.id, OR: [{ id: root }, { rootBuildId: root }] }, orderBy: { createdAt: "desc" }, take: 50, select: { pluginName: true, cyrus: true } });
  const metas = chain.map((c) => readCyrusMeta(c.cyrus));
  const title = metas.find((m) => m.title)?.title ?? chain.find((c) => c.pluginName)?.pluginName ?? "This mod";
  const cat = CATEGORY_BY_KEY[toCategory(metas.find((m) => m.category)?.category)];
  const mod: StudioMod = { buildId: build.id, rootId: root, name: title, category: { key: cat.key, label: cat.label, rgb: cat.rgb } };
  const plan = studioPlanView(await studioPlanOf()(user.id).catch(() => null));
  return { mod, plan };
}
