export const DAPI = "/api/cyrus/designer/v1";

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const r = await fetch(DAPI + path, { cache: "no-store", ...init, headers: { ...(init?.body ? { "content-type": "application/json" } : {}), ...(init?.headers ?? {}) } });
  const j = (await r.json().catch(() => ({}))) as Record<string, unknown>;
  if (!r.ok) throw new ApiError(r.status, String(j.code ?? r.status), String(j.error ?? "Something went wrong."), j);
  return j as T;
}
const send = <T,>(method: string, path: string, body: unknown) => call<T>(path, { method, body: JSON.stringify(body) });

