export function useDesigner(mod: StudioMod) {
  const toast = useToast();
  const [view, setView] = useState<DesignerView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [files, setFiles] = useState<DesignFile[]>([]);
  const [analysis, setAnalysis] = useState<Analysis | null>(null);
  const [checking, setChecking] = useState(false);
  const [saving, setSaving] = useState(false);
  const [draftNote, setDraftNote] = useState<{ kind: "restored" | "stale"; at: string } | null>(null);
  const [autosave, setAutosave] = useState<{ state: "idle" | "saving" | "saved" | "off"; at?: string; reason?: string }>({ state: "idle" });
  const [textures, setTextures] = useState<Record<string, Raster>>({});
  const [itemModels, setItemModels] = useState<ItemModelSpec[]>([]);
  const as = useRef<AutosaveState>(autosaveInit());
  const seq = useRef(0);

  const load = useCallback(async () => {
    try {
      const v = await designerApi.view(mod.rootId);
      setView(v);
      let work = v.saved;
      if (v.draft && !v.draft.stale) { work = v.draft.files; setDraftNote({ kind: "restored", at: v.draft.updatedAt }); }
      else if (v.draft?.stale) setDraftNote({ kind: "stale", at: v.draft.updatedAt });
      else setDraftNote(null);
      setFiles(work);
      as.current = autosaveInit(canonical(work));
      setAnalysis(v.analysis);
      if (v.draft && !v.draft.stale && v.project) setAnalysis(await designerApi.check(v.project.id, work).catch(() => v.analysis));
    } catch (e) { setErr((e as Error).message); }
    // the mod's real textures, for item icons (the studios' own view; never blocks the designer)
    studioApi.assets(mod.rootId).then((a) => { setTextures(Object.fromEntries(a.textures.map((t) => [t.key, renderDoc(t.doc)]))); setItemModels(a.itemModels ?? []); }).catch(() => undefined);
  }, [mod.rootId]);
  useEffect(() => { void load(); }, [load]);

  const pid = view?.project?.id ?? null;
  // server check of the working copy (debounced)
  useEffect(() => {
    if (!pid || !view) return;
    const n = ++seq.current;
    setChecking(true);
    const t = window.setTimeout(async () => {
      try { const a = await designerApi.check(pid, files); if (n === seq.current) setAnalysis(a); }
      catch (e) { if (n === seq.current) toast((e as Error).message, true); }
      finally { if (n === seq.current) setChecking(false); }
    }, 260);
    return () => window.clearTimeout(t);
  }, [files, pid]); // eslint-disable-line react-hooks/exhaustive-deps

  // autosave the draft
  useEffect(() => {
    if (!pid || !view || autosave.state === "off") return;
    as.current = autosaveEdit(as.current, Date.now(), canonical(files));
    const due = autosaveDueIn(as.current, Date.now());
    if (due === null) return;
    const t = window.setTimeout(async () => {
      const sha = canonical(files);
      setAutosave({ state: "saving" });
      try {
        const r = await designerApi.putDraft(pid, files, view.headRevisionId);
        as.current = autosaveDone(as.current, sha);
        setAutosave({ state: "saved", at: r.updatedAt ?? new Date().toISOString() });
      } catch (e) { setAutosave({ state: "off", reason: (e as Error).message }); }
    }, due);
    return () => window.clearTimeout(t);
  }, [files, pid]); // eslint-disable-line react-hooks/exhaustive-deps

  const saved = view?.saved ?? [];
  const changed = useMemo(() => changedIds(saved, files), [saved, files]);
  const savedParams = useMemo(() => new Map((view?.analysis?.params ?? []).map((p) => [p.path, p])), [view]);
  const params = analysis?.params ?? view?.analysis?.params ?? [];

  const save = useCallback(async (): Promise<boolean> => {
    if (!pid || !view) return false;
    setSaving(true);
    try {
      const r = await designerApi.save(pid, files, view.headRevisionId);
      toast(`Saved as revision ${r.seq}${r.configOnly ? " (config.yml only)" : ` (${r.javaChanged.length} Java files change)`}`);
      await load();
      return true;
    } catch (e) {
      if (e instanceof ApiError && e.body.analysis) setAnalysis(e.body.analysis as Analysis);
      toast((e as Error).message, true);
      return false;
    } finally { setSaving(false); }
  }, [pid, view, files, load, toast]);
  const discard = useCallback(async () => {
    setFiles(saved);
    as.current = autosaveInit(canonical(saved));
    setDraftNote(null);
    if (pid) await designerApi.dropDraft(pid).catch(() => undefined);
  }, [saved, pid]);

  return { view, err, files, setFiles, analysis, checking, saving, changed, saved, savedParams, params, save, discard, draftNote, setDraftNote, autosave, textures, itemModels, pid, reload: load };
}

export function PendingBar({ d, labels, idle }: { d: Designer; labels: (id: string) => string; idle?: string }) {
  const a = d.analysis;
  const vErr = a ? a.files.reduce((n, f) => n + f.errors.length, 0) + a.modErrors.length : 0;
  const errors = a ? vErr || (a.compile.ok ? 0 : Math.max(1, a.compile.errors.length)) : 0;
  const nextSeq = (d.view?.headSeq ?? 0) + 1;
  if (!d.changed.length) {
    return <div className="dz-pend idle"><b>No changes.</b> {idle ?? <>Edit here or in the graph; value edits change only <span className="mono">config.yml</span>.</>}</div>;
  }
  const diff = a?.diff;
  const valueEdits = diff ? diff.configOnly : false;
  return (
    <div className="dz-pend" role="status">
      <b>{d.changed.length === 1 ? labels(d.changed[0]) : `${d.changed.length} designs`} changed</b>{diff ? (valueEdits ? " · no Java change" : ` · ${diff.javaChanged.length} Java file${diff.javaChanged.length === 1 ? "" : "s"} change`) : ""}
      <div className="files" title="What the next build ships: the server recompiled the whole mod with your edit">
        {diff ? (
          valueEdits
            ? <><span className="ch">M config.yml</span> · config_version {diff.configVersion.from} → {diff.configVersion.to} · {diff.unchanged} files unchanged</>
            : <><span className="ch">{diff.javaChanged.slice(0, 3).map((p) => `M ${p.split("/").pop()}`).join(" · ")}{diff.javaChanged.length > 3 ? ` +${diff.javaChanged.length - 3}` : ""}</span> · config_version {diff.configVersion.from} → {diff.configVersion.to} · needs a rebuild</>
        ) : d.checking ? "checking…" : "not compiled (fix the errors first)"}
      </div>
      <div className="act">
        <button type="button" className="cys-btn sm" onClick={() => void d.discard()}>Discard</button>
        <button type="button" className="cys-btn sm primary" disabled={!!errors || d.checking || d.saving || !a} onClick={() => void d.save()}>
          <DI n="check" />{errors ? `Fix ${errors} error${errors === 1 ? "" : "s"} first` : d.saving ? "Saving…" : `Save as revision ${nextSeq}`}
        </button>
      </div>
      <p className="cys-hint" style={{ margin: "8px 0 0" }}>Saved revisions stay in Cyrus: builds do not use designer edits yet.</p>
    </div>
  );
}

/** Autosave + restored-draft line under the header. */
export function DraftLine({ d }: { d: Designer }) {
  if (d.draftNote?.kind === "stale") {
    return (
      <div className="dz-banner warn" role="status"><DI n="warn" /><span><b>An older draft exists.</b> The mod changed after it was autosaved, so it was not restored.</span><span className="sp" />
        <button type="button" className="cys-btn xs" onClick={() => { void d.discard(); }}>Discard draft</button></div>
    );
  }
  if (d.draftNote?.kind === "restored" && d.changed.length) {
    return (
      <div className="dz-banner" role="status"><DI n="restore" /><span><b>Restored your unsaved edits</b> from {new Date(d.draftNote.at).toLocaleString()}.</span><span className="sp" />
        <button type="button" className="cys-btn xs" onClick={() => void d.discard()}>Discard</button></div>
    );
  }
  return null;
}
export const autosaveText = (d: Designer) => (d.autosave.state === "off" ? "autosave off" : d.autosave.state === "saving" ? "saving draft…" : d.autosave.state === "saved" && d.changed.length ? "draft saved" : d.changed.length ? "unsaved" : "saved");

export function Loading({ what }: { what: string }) { return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading {what}…</div>; }

