// Cyrus r31: a revision saved in the Designer Studio becomes a build with NO model call. The base build's workspace is
// copied, the studio's designs replace assets/designs/*.json (the same ids; anything else is refused), the designs are
// checked (no repair, no drop: a failing edit fails the build) and compiled into the sources like a model build. When the
// only source file that changed is src/main/resources/config.yml (a parameter edit), no javac runs: the base jar's
// entries are repacked with the new config.yml, so the jar differs from the base in config.yml only. Anything else
// (a structural edit) is compiled with javac from the regenerated sources. Then the usual scan and finish.
function srcDiff(baseWs, ws) {
  const a = new Map(listFiles(baseWs, "src").map((f) => [f.rel, f.abs]));
  const b = new Map(listFiles(ws, "src").map((f) => [f.rel, f.abs]));
  const out = [];
  for (const k of new Set([...a.keys(), ...b.keys()])) if (!a.has(k) || !b.has(k) || !fs.readFileSync(a.get(k)).equals(fs.readFileSync(b.get(k)))) out.push(k);
  return out.sort();
}
async function repackConfigOnly(ws, baseJar) {
  const out = path.join(ws, "build/classes");
  rmrf(path.join(ws, "build")); fs.mkdirSync(out, { recursive: true });
  const x = await run("jar", ["--extract", "--file", baseJar], { cwd: out, env: childEnv(false), timeout: 60000 });
  if (x.code !== 0) return { ok: false, errors: (x.err || "could not read the base jar").slice(0, 2000) };
  fs.copyFileSync(path.join(ws, "src/main/resources/config.yml"), path.join(out, "config.yml"));
  const j = await packJar(ws, out);
  if (!j.ok) return j;
  return { ok: true, jar: j.jar, classes: out, warnings: [] };
}
async function runDesignerEdit(rec) {
  const ctl = { child: null, cancelled: false };
  running.set(rec.id, ctl);
  const started = Date.now();
  rec.startedAt = now();
  const ws = path.join(WORK, rec.id);
  const finalWs = path.join(dirOf(rec.id), "ws");
  try {
    rmrf(ws);
    const baseWs = path.join(dirOf(rec.baseBuildId), "ws");
    const baseJar = path.join(dirOf(rec.baseBuildId), "artifact.jar");
    if (!fs.existsSync(baseWs) || !fs.existsSync(baseJar)) throw fail("bad_request", "The earlier build this edit is based on is no longer available.");
    copyDir(baseWs, ws, (s2, e) => !(e.isDirectory() && e.name === "build" && path.dirname(s2) === baseWs));
    setStage(rec, "compiling", "Applying your designer edit (no AI model is used)");
    rec.attempts = 1;
    const have = DZS.listDesignFiles(ws).map((f) => f.rel).sort().join(",");
    const want = rec.designEdit.files.map((f) => `${DZS.DESIGN_DIR}/${f.id}.json`).sort().join(",");
    if (have !== want) throw fail("bad_request", "A designer edit holds exactly the mod's designs; adding, removing or renaming a design needs a change build.", `have ${have}; sent ${want}`);
    for (const f of rec.designEdit.files) fs.writeFileSync(path.join(ws, DZS.DESIGN_DIR, `${f.id}.json`), JSON.stringify(f.spec, null, 2) + "\n");
    keepUnchangedSpecs(rec, ws);
    sanitizeWorkspace(ws, rec);
    const secretHits = scanSecrets(listFiles(ws), [...SECRETS, ...credentialSecrets()]);
    if (secretHits.length) { rmrf(ws); throw fail("safety", "The edited designs were blocked by our safety checks.", "secret-scan"); }
    const dz = DZS.checkWorkspaceDesigns(ws, { namespace: rec.assets.namespace, mcVersion: rec.mcVersion });
    const bad = dz.results.filter((r) => !r.ok);
    if (dz.problems.length || bad.length) throw fail("compile", "The edited designs did not pass the design checks, so nothing was built.", [...dz.problems, ...bad.flatMap((r) => r.problems)].slice(0, 12).join("\n"));
    designRound(ws, rec, { assetRepairs: MAX_ASSET_REPAIRS }, MAX_REPAIRS); // compiles; never repairs or drops here
    const v = validate(ws, rec);
    if (v.problems.length) throw fail("compile", "The edited designs could not be turned into a plugin.", v.problems.join("\n"));
    const changed = srcDiff(baseWs, ws);
    const configOnly = changed.length === 1 && changed[0] === "src/main/resources/config.yml";
    rec.designEdit.changed = changed;
    rec.designEdit.configOnly = configOnly;
    let c;
    if (configOnly) {
      setStage(rec, "compiling", "Only config.yml changed: repacking the existing plugin (no recompile)");
      c = await repackConfigOnly(ws, baseJar);
      if (!c.ok) throw fail("compile", "The plugin could not be repacked with the new settings.", c.errors);
    } else if (!changed.length) {
      throw fail("bad_request", "These designs produce exactly the plugin you already have; nothing to build.");
    } else {
      setStage(rec, "compiling", `Compiling against Paper ${rec.mcVersion} (${changed.length} source file${changed.length > 1 ? "s" : ""} changed)`);
      c = await timedCompile(ws, rec, ctl);
      if (ctl.cancelled) throw fail("cancelled", "Build cancelled.");
      if (!c.ok) throw fail("compile", "The edited designs did not compile.", c.errors);
    }
    event(rec, "compiling", configOnly ? "Repacked with the new config.yml" : "Compiled successfully");
    setStage(rec, "scanning", "Running the safety check");
    const findings = scanFindings(ws, c, rec);
    const blocks = findings.filter((f) => f.severity === "block");
    if (blocks.length) { rec.safety = { verdict: "block", findings }; throw fail("safety", `The plugin was blocked by our safety check: it ${blocks[0].message}.`, blocks.map((b) => `${b.rule} ${b.where}: ${b.evidence}`).join("\n")); }
    const warns = findings.filter((f) => f.severity === "warn");
    rec.safety = { verdict: warns.length ? "warn" : "pass", findings };
    await finish(rec, ws, c, v.yml);
    rec.summary.changes = configOnly ? "Designer edit: settings only. config.yml changed; every other file in the plugin is the same." : `Designer edit: ${changed.length} source file${changed.length > 1 ? "s" : ""} regenerated from the edited designs and recompiled.`;
  } catch (e) {
