/**
 * Cyrus r31: build a Designer Studio revision. NO model call (so no tokens are held or charged, and designers are not
 * plan-gated, owner decision): the service copies the base build's workspace, swaps in the revision's designs and
 * compiles them (a config.yml-only edit repacks the base jar with the new config.yml). Same account rules as any build:
 * owned + succeeded base, suspension, game switch, rate limits, at most MAX_INFLIGHT running.
 */
export async function createDesignerBuild(user: User, input: { baseBuildId: string; revisionId: string; seq: number; configOnly: boolean; files: { id: string; spec: unknown }[] }): Promise<CreateBuildResult> {
  const base = await db.modBuild.findUnique({ where: { id: input.baseBuildId } });
  if (!base || base.userId !== user.id) return fail(404, { error: "Not found" });
  if (base.status !== "succeeded") return fail(400, { error: "You can only build on a version that finished." });
  if (await cyrusSuspension(user.id, "build")) return fail(403, { error: "Cyrus building is paused on this account. Contact support if you think this is a mistake.", code: "suspended" });
  if (!(await cyrusGameBuildable("minecraft"))) return fail(503, { error: "Cyrus building for Minecraft is paused right now. Please try again later.", code: "game_disabled" });
  for (const [k, max, windowMs] of [["mb:create:min", 3, 60_000], ["mb:create:hour", 20, 3_600_000]] as const) {
    const rl = checkRateLimit(`${k}:${user.id}`, { max, windowMs });
    if (!rl.ok) return fail(429, { error: `You're building fast! Try again in ${rl.retryAfterSec}s.` });
  }
  const inflight = await db.modBuild.count({ where: { userId: user.id, status: { notIn: ["succeeded", "failed"] } } });
  if (inflight >= MAX_INFLIGHT) return fail(429, { error: "You already have builds running. Wait for one to finish first." });
  const id = "mb" + randomBytes(10).toString("hex");
  const changeRequest = `Designer edit: revision ${input.seq}${input.configOnly ? " (settings only)" : ""}`;
  const prev = readCyrusMeta(base.cyrus);
  const cyrus: CyrusMeta = { ...(prev.model ? { model: prev.model } : {}), designer: { revisionId: input.revisionId, seq: input.seq, configOnly: input.configOnly } };
  await db.modBuild.create({ data: { id, userId: user.id, prompt: base.prompt, changeRequest, baseBuildId: base.id, rootBuildId: base.rootBuildId ?? base.id, mcVersion: base.mcVersion, pluginName: base.pluginName, cyrus } });
  try {
    await svcCreate({ id, prompt: base.prompt, mcVersion: base.mcVersion, baseBuildId: await serviceBuildId(base.id), changeRequest, designEdit: { revisionId: input.revisionId, files: input.files } });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: msg, finishedAt: new Date() } });
    console.error("[modbuilder] designer build failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: "modbuilder.designer_build", detail: id } }).catch(() => {});
  const fresh = await db.modBuild.findUnique({ where: { id } });
  return { ok: true, status: 201, build: toView(fresh!), reserved: null };
}
EOF

