/** The head revision, when it is a designer save (an "edited" revision holding edited design rows). */
function designerHead(L: Loaded): { revisionId: string; seq: number; configOnly: boolean } | null {
  if (!L.head || L.head.kind !== "edited") return null;
  const rows = L.rows.filter((r) => r.revisionId === L.head!.id && r.kind === "design" && r.origin === "edited");
