/** Build the saved designer revision (no model). Fails closed: shipping not wired / switched off answers 404. */
export async function buildRevision(deps: DesignerDeps, userId: string, projectId: string, revisionId: string): Promise<{ buildId: string; configOnly: boolean }> {
  const s = deps.ship;
  if (!s || !s.buildsOn()) throw new StudioError(404, "not_found", "Not found");
  const project = await ownedProject(deps, userId, projectId);
  const L = await load(deps, userId, project);
  const head = designerHead(L);
  if (!head || head.revisionId !== revisionId) throw new StudioError(409, "stale_head", "Only the newest saved designer revision can be built. Reload to see it.");
  const prev = await s.latest(userId, L.chain.rootBuildId);
  if (prev && prev.revisionId === revisionId && prev.status !== "failed") throw new StudioError(409, "already_built", "This revision is already being built.", { buildId: prev.id });
  const a = analyzeMod(L.files, L.ctx, L.files);
  if (!a.ok || !a.compile.ok) throw new StudioError(422, "invalid", "This revision no longer validates; open it and fix the errors first.");
