"use client";
// Cyrus r31: ship a saved designer revision. Build it (no AI model, no tokens; a settings-only edit repacks the jar with
// the new config.yml) -> poll the build -> send it to one server through the delivery enqueue API
// (/api/cyrus/delivery/v1, which re-checks ownership, compatibility and every acknowledgement server side) -> poll the
// delivery's status read model. Shown only when the host wired shipping AND CYRUS_DESIGNER_BUILDS=1.
import { useEffect, useState } from "react";
import type { Designer } from "./shared";
import { designerApi } from "./api";
import { DI } from "./icons";

type Ack = { id: string; text?: string; label?: string };
type Status = { state: string; pending: boolean; ok: boolean | null; headline: string; needsAttention: boolean; error: string | null };

async function j(url: string, init?: RequestInit) {
  const r = await fetch(url, { cache: "no-store", ...init, headers: init?.body ? { "content-type": "application/json" } : undefined });
  return { status: r.status, body: (await r.json().catch(() => ({}))) as Record<string, unknown> };
}

export function ShipBar({ d }: { d: Designer }) {
  const ship = d.view?.ship;
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [build, setBuild] = useState<{ id: string; status: string; error: string | null } | null>(ship?.build ?? null);
  const [server, setServer] = useState("");
  const [acks, setAcks] = useState<Ack[]>([]);
  const [acked, setAcked] = useState<string[]>([]);
  const [job, setJob] = useState<{ id: string; status: Status | null } | null>(null);
  useEffect(() => { setBuild(ship?.build ?? null); }, [ship?.build?.id, ship?.build?.status]); // eslint-disable-line react-hooks/exhaustive-deps

  // poll a running build
  useEffect(() => {
