function loadJavaReleases() {
  const map = {};
  const candidates = [process.env.MB_REGISTRY, "/opt/mb/app/registry.json", path.join(__dirname, "../../lib/cyrus/versions/registry.json")].filter(Boolean);
  for (const f of candidates) {
    try {
