      for (const v of reg.versions || []) if (v && v.buildable === true && Number(v.javaRelease) === 25) map[String(v.id)] = 25;
      for (const v of reg.versions || []) if (v && Array.isArray(v.capabilities) && v.capabilities.includes("itemModelDefinitions") && v.resourcePack) ITEM_MODEL_VERSIONS.add(String(v.id));
      for (const v of reg.versions || []) if (v && v.buildable === true && Array.isArray(v.capabilities) && v.capabilities.includes("animatedCreatures")) CREATURE_VERSIONS.add(String(v.id));
      REGISTRY_FILE = f;
      return map;
    } catch { /* try the next candidate */ }
  }
  return map;
}
