// REAL run on node-2 (Cyrus r31, not part of the unit suite): a Designer Studio edit reaches a server.
//   scripts/devhost run --lock -- npx tsx test/cyrus-designer-ship-real.ts --local [--out f.json]
// 1. base build: the Void Arsenal golden designs compiled (TS compiler) + real javac + reproducible jar, stored as a
//    succeeded build in a throwaway data dir of the REAL build service (services/modbuilder/server.js, real JDK 21 javac
//    and jar on PATH, no Claude CLI: a designer edit never calls a model)
// 2. the studio edit (setParamValue: void_pull cooldown 160 -> 100), POSTed with the exact body createDesignerBuild sends
// 3. the service builds it: expected config.yml only -> base jar repacked, every other entry byte-identical
// 4. delivery: the portal function (handleRequestDelivery) -> the real job body + orchestrator -> a disposable server dir
//    that already runs the base jar with its v1 config.yml -> ONE Test Flight boot (real Paper) with the RCON check
//    `voidarsenal params void_reaper` (cooldown 100, not 160) -> the status read model; the server dir is removed.
import { execFileSync, spawn, type ChildProcess } from "node:child_process";
import { createHash } from "node:crypto";
import { cpSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { compileDesigns } from "../lib/cyrus/designer/compile";
import { setParamValue, type DesignFile } from "../lib/cyrus/designer/studio/edit";
import { canonicalJson } from "../lib/cyrus/assets/textures";
import { indexZip, readEntry } from "../lib/cyrus/inventory/zipread";
import { runTestFlight, type Remote, type RunResult } from "../lib/cyrus/testflight/client";
import type { RconCheck, TestFlightSpec } from "../lib/cyrus/testflight/types";
import { LocalGuestFs } from "../lib/mods/guest-fs";
import { handleDeliveryStatus, handleRequestDelivery } from "../lib/cyrus/delivery/api";
import type { DeliveryHost, HealthReport, ServerSession, TxnFs } from "../lib/cyrus/delivery/types";
import { goldenDesigns, GOLDEN_NS, GOLDEN_PLUGIN } from "../scripts/cyrus/designer-golden";
import { MemPortal, makeBuild, post } from "./_cyrus-delivery-memqueue";

const ROOT = path.resolve(__dirname, "..");
const TF = "/tank/nxeon-build/tmp/testflight";
const RUN = `/tank/nxeon-build/tmp/cyrus-r31/run-${Date.now().toString(36)}`;
const VERSION = "1.21.11";
const JDK = `${TF}/jdk/21`;
const KEY = "r31-flight-key-0123456789";
const BASE = "/opt/mc";
const P = "items.void_reaper.abilities.void_pull.";
const ENV = { CYRUS_DELIVERY: "1", CYRUS_MANAGED_PLUGINS_REAL: "1" };
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const arg = (k: string, d: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : d; };
const walk = (d: string): string[] => readdirSync(d).flatMap((n) => { const p = path.join(d, n); return statSync(p).isDirectory() ? walk(p) : [p]; });
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
const REMOTE = process.argv.includes("--local") ? localRemote : undefined;

function entries(jar: Buffer): Map<string, string> {
  const z = indexZip(jar);
  if (!z.ok) throw new Error(z.error);
  const m = new Map<string, string>();
  for (const e of z.zip.entries) { if (e.dir) continue; const r = readEntry(z.zip, e); if (!r.ok) throw new Error(r.error); m.set(e.name, sha(r.data)); }
  return m;
}

/** 1. the base build, stored the way the service stores a succeeded designer build. */
function seedBase(data: string, files: DesignFile[]): { jar: Buffer; jarName: string } {
  const c = compileDesigns(files, { version: VERSION, namespace: GOLDEN_NS, pluginName: GOLDEN_PLUGIN, assets: { models: [] } });
  if (!c.ok) throw new Error(`compile: ${JSON.stringify(c.errors.slice(0, 3))}`);
  const dir = path.join(data, "builds", "b_r31_base");
  const ws = path.join(dir, "ws");
  for (const g of ["build.gradle.kts", "settings.gradle.kts"]) { mkdirSync(ws, { recursive: true }); cpSync(path.join(ROOT, "services/modbuilder/template", g), path.join(ws, g)); }
  for (const f of c.files) { const p = path.join(ws, f.path); mkdirSync(path.dirname(p), { recursive: true }); writeFileSync(p, f.content); }
  for (const f of files) { const p = path.join(ws, "assets/designs", `${f.id}.json`); mkdirSync(path.dirname(p), { recursive: true }); writeFileSync(p, canonicalJson(f)); }
  writeFileSync(path.join(ws, "modbuilder.json"), JSON.stringify({ name: GOLDEN_PLUGIN, version: "1.0.0", tagline: "Void Arsenal", summary: "Designer items." }));
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const cp = readFileSync(`${TF}/classpath/${VERSION}.txt`, "utf8").replace(/\n/g, "").trim();
  execFileSync(`${JDK}/bin/javac`, ["-J-Xmx768m", "--release", "21", "-proc:none", "-encoding", "UTF-8", "-cp", cp, "-d", classes, ...walk(path.join(ws, "src/main/java")).filter((f) => f.endsWith(".java"))], { stdio: ["ignore", "pipe", "pipe"] });
  cpSync(path.join(ws, "src/main/resources"), classes, { recursive: true });
  const list = walk(classes).map((f) => path.relative(classes, f)).sort();
  execFileSync(`${JDK}/bin/jar`, ["--create", "--file", path.join(dir, "artifact.jar"), "--date", "2026-01-01T00:00:00Z", ...list.flatMap((e) => ["-C", classes, e])]);
  rmSync(classes, { recursive: true, force: true });
  const jar = readFileSync(path.join(dir, "artifact.jar"));
  const jarName = `${GOLDEN_PLUGIN}-1.0.0.jar`;
  const now = new Date().toISOString();
  writeFileSync(path.join(dir, "build.json"), JSON.stringify({
    id: "b_r31_base", status: "succeeded", prompt: "Void Arsenal designer items (r31 flight base)", changeRequest: null, baseBuildId: null, mcVersion: VERSION, pluginName: GOLDEN_PLUGIN,
    assets: { texture: false, sound: false, library: false, namespace: GOLDEN_NS, design: true }, events: [], usage: { stages: {} }, warnings: [], files: [], attempts: 1, repairs: 0, costUsd: 0,
    jar: { name: jarName, size: jar.length, sha256: sha(jar) }, createdAt: now, finishedAt: now,
  }));
  return { jar, jarName };
}

function startService(data: string, port: number): Promise<ChildProcess> {
  const cpDir = path.join(RUN, "cp");
  mkdirSync(cpDir, { recursive: true });
  cpSync(`${TF}/classpath/${VERSION}.txt`, path.join(cpDir, `${VERSION}.txt`));
  const child = spawn(process.execPath, [path.join(ROOT, "services/modbuilder/server.js")], {
    env: { PATH: `${JDK}/bin:${process.env.PATH}`, HOME: RUN, PORT: String(port), MB_DATA: data, MB_WORK: path.join(RUN, "work"), MB_TEMPLATE: path.join(ROOT, "services/modbuilder/template"), MB_CP_DIR: cpDir, MODBUILDER_API_KEY: KEY, MB_VERSIONS: VERSION, MB_GUARD: "off", NODE_PATH: path.join(ROOT, "node_modules") } as unknown as NodeJS.ProcessEnv,
    stdio: ["ignore", "ignore", "pipe"],
  });
  let err = "";
  child.stderr?.on("data", (d) => { err += d; if (err.length > 20000) err = err.slice(-10000); });
  return (async () => {
    for (let i = 0; i < 100; i++) { try { if ((await (await fetch(`http://127.0.0.1:${port}/health`)).json()).ok) return child; } catch { /* starting */ } await sleep(200); }
    child.kill("SIGKILL"); throw new Error(`service did not start: ${err.slice(-2000)}`);
  })();
}

async function fly(spec: TestFlightSpec): Promise<RunResult> {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: REMOTE });
    if (r.report.status !== "busy") return r;
    console.log(`node-2 busy, retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error("node-2 stayed busy");
}

/** A server that is a directory; its restart is ONE real Test Flight boot of its current plugins with the RCON checks. */
function flightHost(root: string, rcon: RconCheck[], flights: unknown[]): DeliveryHost {
  const fs = new LocalGuestFs(root);
  let last: RunResult | null = null;
  const local = (p: string) => path.join(root, p);
  const session: ServerSession = {
    fs, base: BASE, levelName: "world", mcVersion: VERSION,
    async restart() {
      const plugins = readdirSync(local(`${BASE}/plugins`)).filter((n) => n.endsWith(".jar")).sort().map((n) => ({ localPath: local(`${BASE}/plugins/${n}`) }));
      // the server's existing plugin data (the base's v1 config.yml) goes in with the boot
      const cfg = local(`${BASE}/plugins/${GOLDEN_PLUGIN}/config.yml`);
      const pre: RconCheck[] = [];
      try { pre.push({ id: "old-config-on-disk", writeFile: { path: `plugins/${GOLDEN_PLUGIN}/config.yml`, content: readFileSync(cfg, "utf8") }, command: `${GOLDEN_PLUGIN.toLowerCase()} reload`, expect: ["config"] }); } catch { /* fresh server */ }
      const spec: TestFlightSpec = { version: VERSION, plugins, rcon: [...pre, ...rcon], timeouts: { bootSec: 240, totalSec: 600 } };
      try {
        const t0 = Date.now();
        last = await fly(spec);
        flights.push({ at: new Date().toISOString(), overall: last.summary.overall, checks: last.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence.slice(0, 12) })), bootMs: last.report.bootMs, wallMs: Date.now() - t0, runId: last.report.runId, paper: last.report.engine?.paper ?? null });
        console.log(`  flight: ${last.summary.overall} (${last.report.checks.map((c) => `${c.id}=${c.status}`).join(" ")})`);
        return { ok: true };
      } catch (e) { last = null; return { ok: false, error: (e as Error).message }; }
    },
    async health(): Promise<HealthReport> {
      const r = last?.report;
      if (!r) return { real: true, cameUp: false, answered: false, pluginsEnabled: [], errorLines: [], datapacksLoaded: [], evidence: ["no flight"] };
      const c = (id: string) => r.checks.find((x) => x.id === id);
      const pe = c("plugins_enabled"), log = c("startup_log_clean"), rc = c("rcon_checks");
      return {
        real: true, cameUp: c("boot_done")?.status === "pass", answered: rc?.status === "pass",
        pluginsEnabled: (pe?.evidence ?? []).map((l) => /^(\S+): enabled/.exec(l)?.[1]).filter((n): n is string => !!n),
        errorLines: log?.status === "fail" ? log.evidence.filter((l) => /ERROR|Exception|Caused by/.test(l)).slice(0, 10) : [], datapacksLoaded: [], evidence: (rc?.evidence ?? []).slice(0, 6),
      };
    },
  };
  const writeJar = async (f: TxnFs, target: string, data: Buffer) => { await f.writeFile(`${target}.nxeon-part`, data); await f.rename(`${target}.nxeon-part`, target); };
  return {
    env: ENV,
    async open() { return session; },
    managed: { async ensure({ key }) { return { ok: false, error: `${key} unused` }; }, async release() { return { ok: true, action: "not_held" }; }, async snapshot() { return "[]"; }, async restore() { return { ok: true }; } },
    jar: {
      async install({ fs: f, base, release, previous }) {
        const target = `${base}/plugins/${release.plugin!.jarName}`;
        if (previous?.jar && previous.jar.target !== target && (await f.stat(previous.jar.target))) await f.remove(previous.jar.target);
        await writeJar(f, target, release.plugin!.bytes);
        return { ok: true, target };
      },
      async remove({ fs: f, record }) { if (record.jar && (await f.stat(record.jar.target))) await f.remove(record.jar.target); return { ok: true }; },
    },
  };
}

async function main() {
  const out: Record<string, unknown> = { what: "Cyrus r31: designer edit -> no-model build (real service) -> delivery enqueue -> one real Paper boot (Test Flight) -> RCON", date: new Date().toISOString(), version: VERSION };
  const save = () => { const f = arg("--out", ""); if (f) writeFileSync(f, JSON.stringify(out, null, 1)); };
  mkdirSync(RUN, { recursive: true });
  const data = path.join(RUN, "data");
  mkdirSync(path.join(data, "builds"), { recursive: true });
  const port = 39000 + Math.floor(Math.random() * 900);
  let svc: ChildProcess | null = null;
  const srv = path.join(RUN, "server");
  try {
    const golden = goldenDesigns() as DesignFile[];
    const base = seedBase(data, golden);
    out.base = { jarSha256: sha(base.jar), entries: entries(base.jar).size };
    svc = await startService(data, port);
    // 2. the studio's edit (the same function the editor runs)
    const e = setParamValue(golden, `${P}cooldown_ticks`, 100);
    if (!e.ok) throw new Error(e.error);
    const body = { id: "b_r31_edit1", prompt: "Void Arsenal designer items (r31 flight base)", mcVersion: VERSION, baseBuildId: "b_r31_base", changeRequest: "Designer edit: revision 2 (settings only)", designEdit: { revisionId: "rev_r31_2", files: e.files.map((f) => ({ id: f.id, spec: f })) } };
    const t0 = Date.now();
    const res = await fetch(`http://127.0.0.1:${port}/builds`, { method: "POST", headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: JSON.stringify(body) });
    if (res.status !== 202) throw new Error(`POST /builds ${res.status} ${await res.text()}`);
    let rec: Record<string, unknown> = {};
    for (let i = 0; i < 600; i++) { rec = await (await fetch(`http://127.0.0.1:${port}/builds/b_r31_edit1`, { headers: { Authorization: `Bearer ${KEY}` } })).json(); if (rec.status === "succeeded" || rec.status === "failed") break; await sleep(500); }
    const art = Buffer.from(await (await fetch(`http://127.0.0.1:${port}/builds/b_r31_edit1/artifact`, { headers: { Authorization: `Bearer ${KEY}` } })).arrayBuffer());
    const a = entries(base.jar), b = entries(art);
    const differing = [...new Set([...a.keys(), ...b.keys()])].filter((k) => a.get(k) !== b.get(k)).sort();
    out.build = { status: rec.status, error: rec.error ?? null, ms: Date.now() - t0, model: rec.model, costUsd: rec.costUsd, designEdit: rec.designEdit, events: (rec.events as { message: string }[]).map((x) => x.message), jarSha256: sha(art), sameEntrySet: a.size === b.size && [...a.keys()].every((k) => b.has(k)), differingEntries: differing };
    console.log(`build: ${rec.status} ${JSON.stringify(rec.designEdit)} differing=${differing.join(",")}`); save();
    if (rec.status !== "succeeded") throw new Error("the designer build failed");
    // 4. delivery: a server already running the base jar with its v1 config.yml
    const baseCfg = (() => { const z = indexZip(base.jar); if (!z.ok) throw new Error(z.error); const en = z.zip.entries.find((x) => x.name === "config.yml")!; const r = readEntry(z.zip, en); if (!r.ok) throw new Error(r.error); return r.data; })();
    for (const d of ["plugins", "world/datapacks", `plugins/${GOLDEN_PLUGIN}`]) mkdirSync(path.join(srv, BASE.slice(1), d), { recursive: true });
    writeFileSync(path.join(srv, BASE.slice(1), "server.properties"), "level-name=world\n");
    writeFileSync(path.join(srv, BASE.slice(1), "version_history.json"), JSON.stringify({ currentVersion: `${VERSION} (MC: ${VERSION})` }));
    writeFileSync(path.join(srv, BASE.slice(1), "plugins", base.jarName), base.jar);
    writeFileSync(path.join(srv, BASE.slice(1), `plugins/${GOLDEN_PLUGIN}/config.yml`), baseCfg);
    const flights: unknown[] = [];
    const rcon: RconCheck[] = [
      { id: "plugins", command: "plugins", expect: [GOLDEN_PLUGIN] },
      { id: "edited-value-live", command: "voidarsenal params void_reaper", expect: [`${P}cooldown_ticks=100`], expectNot: [`${P}cooldown_ticks=160`, "internal error"] },
    ];
    const host = flightHost(srv, rcon, flights);
    const m = new MemPortal();
    m.user = { id: "u_owner" };
    m.servers.set("srv_r31", { id: "srv_r31", userId: "u_owner", name: "r31 flight server", eligible: true });
    m.projects.set("cp_r31flight1", { id: "cp_r31flight1", namespace: GOLDEN_NS, userId: "u_owner", rootBuildId: "b_r31_base" });
    m.addBuild(makeBuild({ id: "b_r31_edit1", userId: "u_owner", rootBuildId: "b_r31_base", pluginName: GOLDEN_PLUGIN, jarName: base.jarName, jar: art, mcVersion: VERSION, project: { id: "cp_r31flight1", namespace: GOLDEN_NS }, revisionId: "rev_r31_2" }), art);
    const api = m.apiDeps(ENV);
    const q = await handleRequestDelivery(post({ op: "deliver", buildId: "b_r31_edit1", serverId: "srv_r31", acked: ["restart"] }, { "idempotency-key": "r31-flight-0001" }), api);
    const qb = await q.json();
    if (!qb.jobId) throw new Error(`enqueue refused: ${q.status} ${JSON.stringify(qb)}`);
    await m.runNext(m.jobDeps(ENV, () => host));
    const st = (await (await handleDeliveryStatus(qb.jobId, api)).json()).status;
    out.delivery = { request: { http: q.status, jobId: qb.jobId, parts: qb.parts }, status: st, jobStatus: m.jobs[0]?.status, jobError: m.jobs[0]?.error ?? null, plugins: readdirSync(path.join(srv, BASE.slice(1), "plugins")).sort() };
    out.flights = flights;
    console.log(`delivery: ${st?.state} - ${st?.headline}`);
  } finally {
    save();
    if (svc) svc.kill("SIGKILL");
    rmSync(srv, { recursive: true, force: true });
    rmSync(path.join(RUN, "work"), { recursive: true, force: true });
  }
  if (!process.argv.includes("--out")) console.log(JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

