191:  return json(200, { packId, versionId: t.versionId, serverId, installable: s.blocking.length === 0, findings: s.view.findings, requiredAcks: [...s.required, "restart"], serverFindings: s.serverFindings, notes: s.view.notes });
196:  if (rawKey !== null && !CLIENT_KEY_RE.test(rawKey)) return json(400, { error: "Idempotency-Key must be 8-128 letters, digits or _.:-", code: "bad_key" });
