214:  if (!policy) return json(400, { error: "restartPolicy must be now or next_restart.", code: "bad_policy" });
221:  if (s.blocking.length) return json(409, { error: "This pack conflicts with what the server already runs.", code: "blocking_conflicts", findings: s.blocking });
225:  if (missing.length) return json(409, { error: "Confirm every open warning first.", code: "needs_ack", acks: missing.map((id) => ({ id, text: id === "restart" ? ACK_TEXT.restart : s.view.findings.find((f) => f.id === id)?.message ?? "an open warning recorded in the pack" })) });
