/* Cyrus r31 screens: Mod Packs + conflicts, Import your mod, Data packs + worldgen. Ported from the v2 mockups
   (/root/agent-notes/cyrus-designs/v2/src/mod-packs.html, import-mod.html, datapack-studio.html; NOT owner-reviewed)
   onto the shipped studio tokens (../studios/studios.css). Every class is fg-*. One accent (violet = selected /
   primary); green / amber / red only mean pass / warn / fail. Phones get the same content read-only (.fg-edit hidden). */

.cys .fg-ws { flex: 1; min-height: 0; display: grid; grid-template-columns: 260px minmax(0, 1fr) 320px; gap: 12px; padding: 4px 14px 14px; }
.cys .fg-col { display: flex; flex-direction: column; gap: 12px; min-height: 0; min-width: 0; overflow: auto; }
