.cys .fg-body { padding: 0 14px 14px; display: flex; flex-direction: column; gap: 8px; }
.cys .fg-kv { display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 6px 14px; font-size: 12px; }
.cys .fg-kv dt { color: var(--muted); }
.cys .fg-kv dd { margin: 0; font: 500 11.5px/1.35 var(--mono); color: var(--ink); text-align: right; overflow-wrap: anywhere; }
.cys .fg-mono { font: 500 11px/1.4 var(--mono); color: var(--muted); }
.cys .fg-h1 { margin: 0; font: 600 18px/1.2 var(--display); color: var(--ink); }
.cys .fg-sub { font-size: 12px; color: var(--muted); margin: 2px 0 0; }
.cys .fg-row { display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-radius: var(--r); color: var(--ink-2); width: 100%; text-align: left; }
.cys button.fg-row:hover { background: rgb(var(--glow) / .07); }
.cys .fg-row.on { background: rgb(var(--glow) / .13); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); color: var(--ink); }
.cys .fg-row .tx { flex: 1; min-width: 0; }
.cys .fg-row .tx b { display: block; font-weight: 600; font-size: 12.5px; color: var(--ink); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .fg-row .tx small { display: block; font: 400 10.5px/1.3 var(--mono); color: var(--muted); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cys .fg-pills { display: flex; flex-wrap: wrap; gap: 6px; }
.cys .fg-pill { font: 500 11px/1 var(--mono); padding: 6px 9px; border-radius: 8px; border: 1px solid var(--line-2); color: var(--ink-2); background: var(--well); }
.cys .fg-pill.bad { color: var(--bad); border-color: color-mix(in srgb, var(--bad) 45%, transparent); background: var(--bad-soft); }
.cys .fg-pill.warn { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 45%, transparent); background: var(--warn-soft); }
.cys .fg-pill.ok { color: var(--ok); border-color: color-mix(in srgb, var(--ok) 45%, transparent); background: var(--ok-soft); }
.cys button.fg-pill.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.cys .fg-card { border-radius: var(--r-lg); border: 1px solid var(--line); background: var(--well); padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; }
.cys .fg-card.bad { border-color: color-mix(in srgb, var(--bad) 55%, transparent); }
.cys .fg-card.warn { border-color: color-mix(in srgb, var(--warn) 40%, transparent); }
.cys .fg-card .hd { display: flex; align-items: flex-start; gap: 10px; }
.cys .fg-card .hd b { flex: 1; font-size: 13px; color: var(--ink); line-height: 1.3; }
.cys .fg-card .res { font-size: 11.5px; color: var(--ink-2); }
.cys .fg-card .res .k { font: 600 10.5px/1 var(--mono); color: var(--muted); margin-right: 6px; }
.cys .fg-ack { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--ink-2); }
.cys .fg-ack.need { color: var(--warn); }
.cys .fg-banner { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border-radius: var(--r-lg); border: 1px solid color-mix(in srgb, var(--warn) 45%, transparent); background: var(--warn-soft); font-size: 12px; color: var(--ink); }
.cys .fg-banner.bad { border-color: color-mix(in srgb, var(--bad) 55%, transparent); background: var(--bad-soft); }
.cys .fg-banner.ok { border-color: color-mix(in srgb, var(--ok) 45%, transparent); background: var(--ok-soft); }
.cys .fg-steps { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 10px 14px; font-size: 12px; color: var(--ink-2); }
.cys .fg-steps .st { display: inline-flex; align-items: center; gap: 6px; }
