.cys .fg-steps .st.fail i { border-color: var(--bad); background: radial-gradient(circle, var(--bad) 0 35%, transparent 40%); }
.cys .fg-steps .sep { flex: 0 0 14px; height: 1px; background: var(--line-2); }
.cys .fg-list { display: flex; flex-direction: column; gap: 4px; margin: 0; padding: 0; list-style: none; font-size: 12px; color: var(--ink-2); }
.cys .fg-list li { display: flex; gap: 8px; align-items: baseline; }
.cys .fg-list li .r { margin-left: auto; font: 500 10.5px/1 var(--mono); color: var(--muted); }
.cys .fg-input { height: 32px; border-radius: 9px; border: 1px solid var(--line-2); background: var(--well); color: var(--ink); padding: 0 10px; font-size: 12.5px; width: 100%; }
.cys select.fg-input { padding-right: 24px; }
.cys .fg-field { display: flex; flex-direction: column; gap: 4px; font-size: 11px; color: var(--muted); }
.cys .fg-tiles { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.cys .fg-tile { border-radius: 12px; border: 1px solid var(--line); background: var(--well); padding: 10px; font-size: 11px; color: var(--muted); }
.cys .fg-tile b { display: block; color: var(--ink); font-size: 12.5px; margin-bottom: 2px; }
.cys .fg-tile.on { border-color: var(--accent-line); background: var(--accent-soft); }
.cys .fg-vstrip { display: flex; flex-wrap: wrap; gap: 6px; }
.cys .fg-vchip { display: inline-flex; align-items: center; gap: 6px; font: 500 11px/1 var(--mono); padding: 6px 8px; border-radius: 8px; border: 1px solid var(--line-2); background: var(--well); color: var(--ink-2); }
.cys button.fg-vchip.on { border-color: var(--accent-line); background: var(--accent-soft); color: var(--accent-ink); }
.cys .fg-dots { display: inline-flex; gap: 3px; }
.cys .fg-dots span { width: 7px; height: 7px; border-radius: 2px; border: 1px solid var(--line-3); }
.cys .fg-dots span.ok { background: var(--ok); border-color: var(--ok); } .cys .fg-dots span.bad { background: var(--bad); border-color: var(--bad); }
.cys .fg-pre { margin: 0; padding: 10px 12px; border-radius: 10px; background: var(--well); border: 1px solid var(--line); font: 500 11px/1.45 var(--mono); color: var(--ink-2); max-height: 360px; overflow: auto; white-space: pre-wrap; overflow-wrap: anywhere; }
.cys .fg-grid4 { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 8px; }
.cys .fg-ro { display: none; }
.cys .fg-err { color: var(--bad); font-size: 12px; margin: 0; }
.cys .fg-tree { display: flex; flex-direction: column; gap: 2px; padding: 0 8px 12px; }
.cys .fg-tree .grp { display: flex; align-items: center; gap: 8px; padding: 8px 6px 4px; font-size: 12px; color: var(--ink-2); font-weight: 600; }
.cys .fg-tree .grp .n { margin-left: auto; font: 500 10px/1 var(--mono); color: var(--muted); }
.cys .fg-tree button { text-align: left; font: 500 11.5px/1.2 var(--mono); color: var(--muted); padding: 5px 8px 5px 22px; border-radius: 7px; display: flex; align-items: center; }
.cys .fg-tree button::after { content: ""; margin-left: auto; width: 6px; height: 6px; border-radius: 50%; background: var(--ok); }
.cys .fg-tree button.bad::after { background: var(--bad); }
.cys .fg-tree button.on { color: var(--ink); background: rgb(var(--glow) / .13); }
.cys .fg-tabs { display: inline-flex; gap: 4px; padding: 3px; border-radius: 10px; border: 1px solid var(--line); }
.cys .fg-tabs button { font-size: 11.5px; padding: 5px 9px; border-radius: 7px; color: var(--muted); }
.cys .fg-tabs button.on { color: var(--ink); background: var(--accent-soft); }
@container (max-width: 1180px) { .cys .fg-ws { grid-template-columns: 230px minmax(0, 1fr) 290px; } }
@container (max-width: 760px) {
  .cys .fg-ws { display: flex; flex-direction: column; overflow: auto; padding: 4px 12px 24px; }
  .cys .fg-col { overflow: visible; }
  .cys .fg-edit { display: none !important; }
  .cys .fg-ro { display: flex; }
}

