"use client";
// Cyrus r31: Mod Packs + conflicts (/dashboard/cyrus/packs), over /api/cyrus/modpacks/v1 (CYRUS_MODPACKS; install also
// needs CYRUS_DELIVERY). Follows the v2 mockup mod-packs.html, which the owner has NOT reviewed yet. Compose (validate ->
// create), the conflict report (All / Blocking / Warn / Info), the composed pack, then "install as one unit": check
// against a server (read-only) -> EVERY open warning acknowledged (the API refuses otherwise) -> install -> the delivery
// status read model. Phones: read-only.
import { useCallback, useEffect, useMemo, useState } from "react";
import { StudioShell, useToast } from "../studios/StudioShell";
import "./forge.css";

export type PackMember = { buildId: string; name: string; mcVersion: string };
export type PackServer = { id: string; name: string; compatible: boolean; reason?: string };
type Finding = { id: string; class: string; severity: string; message: string; resolution: string; needsAck: boolean };
type BuildView = { ok: boolean; code?: string; errors?: string[]; versionId?: string; members?: { id: string; kind: string; label: string; version: string }[]; counts?: Record<string, number>; findings: Finding[]; openWarnings?: string[]; notChecked?: string[]; compatibility?: unknown; bytes?: number; notes: string[] };
type Pack = { packId: string; name: string; summary: string | null; mcVersion: string; members: { buildId: string }[]; versions: { versionId: string; openWarnings: string[] }[]; latest: string | null };
type ServerCheck = { installable: boolean; findings: Finding[]; requiredAcks: string[]; serverFindings: number; notes: string[] };
type Ack = { id: string; text: string };
type Status = { state: string; pending: boolean; ok: boolean | null; headline: string; needsAttention: boolean };
const API = "/api/cyrus/modpacks/v1";

async function call(url: string, body?: unknown, key?: string) {
  const r = await fetch(url, { method: body === undefined ? "GET" : "POST", cache: "no-store", headers: { ...(body !== undefined ? { "content-type": "application/json" } : {}), ...(key ? { "idempotency-key": key } : {}) }, body: body === undefined ? undefined : JSON.stringify(body) });
  return { status: r.status, body: (await r.json().catch(() => ({}))) as Record<string, unknown> };
}
const SEV: Record<string, { tag: string; label: string }> = { blocking: { tag: "bad", label: "Blocking" }, warn: { tag: "warn", label: "Warn" }, info: { tag: "dim", label: "Info" } };

export function ModPacks({ builds, servers, versions }: { builds: PackMember[]; servers: PackServer[]; versions: string[] }) {
  const toast = useToast();
  const [packs, setPacks] = useState<Pack[] | null>(null);
  const [sel, setSel] = useState<string | null>(null);
  const [draft, setDraft] = useState<{ name: string; mcVersion: string; members: string[] }>({ name: "", mcVersion: versions[0] ?? "1.21.11", members: [] });
  const [report, setReport] = useState<BuildView | null>(null);
  const [filter, setFilter] = useState<"all" | "blocking" | "warn" | "info">("all");
  const [server, setServer] = useState("");
  const [check, setCheck] = useState<ServerCheck | null>(null);
  const [acked, setAcked] = useState<string[]>([]);
  const [ackText, setAckText] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [job, setJob] = useState<{ id: string; status: Status | null } | null>(null);

  const load = useCallback(async () => { const r = await call(API); setPacks(r.status === 200 ? ((r.body.packs as Pack[]) ?? []) : []); }, []);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => {
    if (!job || (job.status && !job.status.pending)) return;
    const t = window.setTimeout(async () => { const r = await call(`/api/cyrus/delivery/v1/${job.id}`); if (r.body.status) setJob({ id: job.id, status: r.body.status as Status }); }, 3000);
    return () => window.clearTimeout(t);
  }, [job]);
  const pack = packs?.find((p) => p.packId === sel) ?? null;
  const composition = pack ? { name: pack.name, mcVersion: pack.mcVersion, members: pack.members.map((m) => ({ buildId: m.buildId })) } : { name: draft.name.trim(), mcVersion: draft.mcVersion, members: draft.members.map((buildId) => ({ buildId })) };

  const validate = async () => {
    setBusy(true); setMsg(null); setCheck(null);
    const r = await call(`${API}/validate`, composition);
    setBusy(false);
    if (r.status !== 200) { setMsg(String(r.body.error ?? "Could not check this pack.")); return; }
    setReport(r.body as unknown as BuildView);
  };
  useEffect(() => { if (pack) void validate(); else setReport(null); setCheck(null); setAcked([]); setJob(null); }, [sel]); // eslint-disable-line react-hooks/exhaustive-deps
  const create = async () => {
    setBusy(true); setMsg(null);
    const r = await call(API, composition);
    setBusy(false);
    if (r.status !== 201) { setMsg(String(r.body.error ?? "The pack was refused.")); if (r.body.findings) setReport(r.body as unknown as BuildView); return; }
    toast("Pack saved");
    await load();
    setSel(String((r.body.pack as Pack).packId));
  };
  const checkServer = async () => {
    if (!pack || !server) return;
    setBusy(true); setMsg(null);
    const r = await call(`${API}/${pack.packId}/conflicts`, { serverId: server });
    setBusy(false);
    if (r.status !== 200) { setMsg(String(r.body.error ?? "Could not check that server.")); return; }
    const c = r.body as unknown as ServerCheck;
    setCheck(c);
    setAckText(Object.fromEntries(c.requiredAcks.map((id) => [id, id === "restart" ? "Restart the server to load the pack." : c.findings.find((f) => f.id === id)?.message ?? "An open warning recorded in the pack."])));
  };
  const install = async () => {
    if (!pack || !server) return;
    setBusy(true); setMsg(null);
    const r = await call(`${API}/${pack.packId}/install`, { serverId: server, acked, restartPolicy: "now" }, `pack-${pack.packId}-${server}-${pack.latest}`.slice(0, 128));
    setBusy(false);
    if (r.status === 409 && r.body.code === "needs_ack") { const a = (r.body.acks as Ack[]) ?? []; setAckText((x) => ({ ...x, ...Object.fromEntries(a.map((y) => [y.id, y.text])) })); setMsg(String(r.body.error)); return; }
    if (r.status >= 400) { setMsg(String(r.body.error ?? "The install was refused.")); return; }
    setJob({ id: String(r.body.jobId), status: (r.body.status as Status) ?? null });
  };

  const findings = check?.findings ?? report?.findings ?? [];
  const counts = useMemo(() => ({ blocking: findings.filter((f) => f.severity === "blocking").length, warn: findings.filter((f) => f.severity === "warn").length, info: findings.filter((f) => f.severity === "info").length }), [findings]);
  const shown = findings.filter((f) => filter === "all" || f.severity === filter);
  const required = check?.requiredAcks ?? [];
  const missing = required.filter((id) => !acked.includes(id));
  const toggle = (id: string, on: boolean) => setAcked((x) => (on ? [...new Set([...x, id])] : x.filter((y) => y !== id)));
  const label = (id: string) => builds.find((b) => b.buildId === id)?.name ?? id;

  return (
    <StudioShell mod={null} trail={[{ label: "Mod Packs", href: "/dashboard/cyrus/packs" }]} current={pack?.name ?? "New pack"} studio={null} kind="modpacks">
      <div className="fg-ws">
        <div className="fg-col">
          <section className="cys-panel cys-glass cys-hairline">
            <div className="cys-ph"><span className="cys-eyebrow">Packs</span><span className="n">{packs?.length ?? "…"}</span></div>
            <div className="fg-body">
              {packs === null ? <p className="cys-hint">Loading…</p> : packs.length === 0 ? <p className="cys-hint">No packs yet. Compose one from your Cyrus mods below.</p> : null}
              {packs?.map((p) => (
                <button key={p.packId} type="button" className={`fg-row ${sel === p.packId ? "on" : ""}`} onClick={() => setSel(p.packId)}>
                  <span className="tx"><b>{p.name}</b><small>{p.members.length} mods · Paper {p.mcVersion} · {p.versions.length} version{p.versions.length === 1 ? "" : "s"}</small></span>
                </button>
              ))}
              <button type="button" className={`fg-row ${sel === null ? "on" : ""}`} onClick={() => setSel(null)}><span className="tx"><b>+ New pack</b><small>compose from your mods</small></span></button>
            </div>
          </section>
          {sel === null ? (
            <section className="cys-panel cys-glass fg-edit">
              <div className="cys-ph"><span className="cys-eyebrow">Compose</span></div>
              <div className="fg-body">
                <label className="fg-field">Name<input className="fg-input" value={draft.name} maxLength={80} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="Guild Survival" /></label>
                <label className="fg-field">Minecraft<select className="fg-input" value={draft.mcVersion} onChange={(e) => setDraft({ ...draft, mcVersion: e.target.value })}>{versions.map((v) => <option key={v} value={v}>Paper {v}</option>)}</select></label>
                <div className="fg-field">Members ({draft.members.length})</div>
                {builds.length === 0 ? <p className="cys-hint">Build a mod with Cyrus first.</p> : builds.map((b) => (
                  <label key={b.buildId} className="fg-ack"><input type="checkbox" checked={draft.members.includes(b.buildId)} onChange={(e) => setDraft({ ...draft, members: e.target.checked ? [...draft.members, b.buildId] : draft.members.filter((x) => x !== b.buildId) })} />{b.name}<span className="fg-mono" style={{ marginLeft: "auto" }}>{b.mcVersion}</span></label>
                ))}
                <div className="fg-pills">
                  <button type="button" className="cys-btn sm" disabled={busy || !draft.name.trim() || !draft.members.length} onClick={() => void validate()}>Check conflicts</button>
                  <button type="button" className="cys-btn sm primary" disabled={busy || !draft.name.trim() || !draft.members.length} onClick={() => void create()}>Save pack</button>
                </div>
                <p className="cys-hint">Composing is never plan-gated. Third-party mods and resource packs inside packs are not supported yet.</p>
              </div>
            </section>
          ) : (
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">Members</span><span className="n">{pack?.members.length}</span></div>
              <div className="fg-body">{pack?.members.map((m) => <div key={m.buildId} className="fg-row"><span className="tx"><b>{label(m.buildId)}</b><small>{m.buildId}</small></span><span className="cys-tag acc">Cyrus</span></div>)}</div>
            </section>
          )}
        </div>

        <div className="fg-col">
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Conflict report</span><span className="fg-mono">{check ? `against ${servers.find((s) => s.id === server)?.name ?? "the server"}` : "pack members against each other"}</span></div>
            <div className="fg-body">
              <div className="fg-pills">
                <span className="fg-pill bad">{counts.blocking} blocking</span>
                <span className="fg-pill warn">{counts.warn} open warning{counts.warn === 1 ? "" : "s"}</span>
                <span className="fg-pill">{counts.info} info</span>
                {report?.notChecked?.length ? <span className="fg-pill">{report.notChecked.length} not checked</span> : null}
              </div>
              <div className="fg-tabs" role="tablist" aria-label="Filter">
                {(["all", "blocking", "warn", "info"] as const).map((f) => <button key={f} type="button" role="tab" aria-selected={filter === f} className={filter === f ? "on" : ""} onClick={() => setFilter(f)}>{f === "all" ? "All" : SEV[f].label}</button>)}
              </div>
              {!report && !check ? <p className="cys-hint">{sel ? "Checking…" : "Pick members and press Check conflicts."}</p> : null}
              {report && !report.ok && report.errors?.length ? <div className="fg-banner bad" role="alert"><span><b>This pack cannot be built as it is.</b> {report.errors.slice(0, 3).join(" · ")}</span></div> : null}
              {(report || check) && !shown.length ? <p className="cys-hint">Nothing in this filter.</p> : null}
              {shown.map((f) => (
                <article key={f.id} className={`fg-card ${f.severity === "blocking" ? "bad" : f.severity === "warn" ? "warn" : ""}`}>
                  <div className="hd"><span className={`cys-tag ${SEV[f.severity]?.tag ?? "dim"}`}>{SEV[f.severity]?.label ?? f.severity}</span><b>{f.message}</b><span className="fg-mono">{f.class}</span></div>
                  {f.resolution ? <div className="res"><span className="k">resolution</span>{f.resolution}</div> : null}
                  {f.needsAck ? (
                    check ? <label className={`fg-ack ${acked.includes(f.id) ? "" : "need"}`}><input type="checkbox" className="fg-edit" checked={acked.includes(f.id)} onChange={(e) => toggle(f.id, e.target.checked)} />{acked.includes(f.id) ? "Acknowledged: keep it and install anyway" : "Open warning: acknowledge it before installing"}</label>
                      : <span className="fg-ack need">Open warning: you acknowledge it when you install</span>
                  ) : null}
                </article>
              ))}
              {report?.notes?.length ? <ul className="fg-list">{report.notes.slice(0, 6).map((n, i) => <li key={i}>{n}</li>)}</ul> : null}
              {msg ? <p className="fg-err" role="alert">{msg}</p> : null}
            </div>
          </section>
        </div>

        <div className="fg-col">
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Composed pack</span>{report?.versionId ? <span className="cys-tag dim">{report.versionId.slice(0, 14)}</span> : null}</div>
            <div className="fg-body">
              {report?.ok ? (
                <dl className="fg-kv">
                  <dt>Members</dt><dd>{report.members?.length}</dd>
                  <dt>Size</dt><dd>{((report.bytes ?? 0) / 1024).toFixed(1)} KB</dd>
                  {Object.entries(report.counts ?? {}).slice(0, 6).map(([k, v]) => <><dt key={`k${k}`}>{k}</dt><dd key={`v${k}`}>{v}</dd></>)}
                  <dt>Open warnings</dt><dd>{report.openWarnings?.length ?? 0}</dd>
                </dl>
              ) : <p className="cys-hint">{report ? "Not buildable yet." : "Nothing composed yet."}</p>}
              {report?.notChecked?.length ? <p className="cys-hint">Not checked: {report.notChecked.slice(0, 4).join(", ")}. Not checked is not a pass.</p> : null}
            </div>
          </section>
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Install as one unit</span></div>
            <div className="fg-body">
              <ol className="fg-list" style={{ listStyle: "decimal", paddingLeft: 18, display: "block" }}>
                <li>The manifest and every file are verified before the server is touched.</li>
                <li>Nothing the pack does not own is overwritten.</li>
                <li>Every path it touches is backed up; a failed health check rolls it all back.</li>
              </ol>
              {!pack ? <p className="cys-hint">Save the pack first.</p> : (
                <>
                  <div className="fg-pills fg-edit">
                    <select className="fg-input" aria-label="Server" value={server} onChange={(e) => { setServer(e.target.value); setCheck(null); setAcked([]); }} style={{ flex: 1 }}>
                      <option value="">Pick a server…</option>
                      {servers.map((s) => <option key={s.id} value={s.id} disabled={!s.compatible}>{s.name}{s.compatible ? "" : ` (${s.reason ?? "not compatible"})`}</option>)}
                    </select>
                    <button type="button" className="cys-btn sm" disabled={!server || busy} onClick={() => void checkServer()}>Check server</button>
                  </div>
                  {check ? (
                    <>
                      {!check.installable ? <div className="fg-banner bad"><span><b>Blocked.</b> Resolve the blocking conflicts first.</span></div> : null}
                      {required.length ? <div className="fg-field">To confirm ({required.length - missing.length} of {required.length})</div> : null}
                      {required.filter((id) => id === "restart" || !findings.some((f) => f.id === id)).map((id) => (
                        <label key={id} className={`fg-ack ${acked.includes(id) ? "" : "need"}`}><input type="checkbox" className="fg-edit" checked={acked.includes(id)} onChange={(e) => toggle(id, e.target.checked)} />{ackText[id] ?? id}</label>
                      ))}
                      <button type="button" className="cys-btn sm primary fg-edit" disabled={busy || !check.installable || missing.length > 0 || !!(job && (!job.status || job.status.pending))} onClick={() => void install()}>
                        {missing.length ? `Acknowledge ${missing.length} more` : busy ? "Starting…" : "Install pack"}
                      </button>
                    </>
                  ) : null}
                  {job ? <div className={`fg-banner ${job.status?.needsAttention ? "bad" : job.status?.ok ? "ok" : ""}`} role="status"><span>{job.status?.headline ?? "Queued…"}{job.status?.needsAttention ? " The server may not be exactly as it was: contact support." : ""}</span></div> : null}
                </>
              )}
              <p className="fg-ro cys-hint">Read-only on a phone: open Mod Packs on a larger screen to compose or install.</p>
            </div>
          </section>
        </div>
      </div>
    </StudioShell>
  );
}

