cd /tank/dev-worktrees/cyrus-r31 && mkdir -p app/dashboard/cyrus/packs app/dashboard/cyrus/import && cat > app/dashboard/cyrus/packs/page.tsx <<'EOF'
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { modBuilderMetadata, requireModBuilderUser } from "@/lib/modbuilder/access";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { modpacksEnabled } from "@/lib/cyrus/modpack/api";
import { readCyrusMeta } from "@/lib/cyrus/meta";
import { MB_VERSIONS } from "@/lib/modbuilder/types";
import { ModPacks } from "@/components/cyrus/forge/ModPacks";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return modBuilderMetadata("Mod Packs · Cyrus");
}

/** Cyrus r31: Mod Packs + conflicts. 404 unless CYRUS_MODPACKS=1 (the API checks everything again on every call). */
export default async function ModPacksPage() {
  const user = await requireModBuilderUser();
  if (!modpacksEnabled(process.env)) notFound();
  const rows = await db.modBuild.findMany({ where: { userId: user.id, status: "succeeded", jarName: { not: null } }, orderBy: { createdAt: "desc" }, take: 100, select: { id: true, rootBuildId: true, pluginName: true, mcVersion: true, cyrus: true } });
  // the newest succeeded build of each mod (chain)
  const seen = new Set<string>();
  const builds = rows.filter((r) => { const k = r.rootBuildId ?? r.id; if (seen.has(k)) return false; seen.add(k); return true; })
    .map((r) => ({ buildId: r.id, name: readCyrusMeta(r.cyrus).title ?? r.pluginName ?? r.id, mcVersion: r.mcVersion }));
  const servers = (await modBuilderServers(user.id)).map((s) => ({ id: s.id, name: s.name, compatible: s.compatible, ...(s.reason ? { reason: s.reason } : {}) }));
  return <ModPacks builds={builds} servers={servers} versions={[...MB_VERSIONS]} />;
}
EOF
