"use client";
// Cyrus r31: Import your mod (/dashboard/cyrus/import), over /api/cyrus/import (setting cyrus_import_enabled). Follows
// the v2 mockup import-mod.html, which the owner has NOT reviewed yet. The upload carries the ownership attestation
// (typed name, the exact text version, the claimed licence); allowlisted dependencies are compile-only and named; the
// scan is the ATTESTED profile and is never shown as "safe" or "passed": only what it found. Phones: read-only.
import { useCallback, useEffect, useState } from "react";
import { StudioShell } from "../studios/StudioShell";
import "./forge.css";

type Detection = { kind: string; buildSystem: string | null; descriptorFile: string | null; name: string | null; version: string | null; main: string | null; apiVersion: string | null; description: string | null; depend: string[]; softdepend: string[]; commands: string[]; permissions: string[]; language: string | null; sourcesComplete: boolean | null; missingClasses: string[]; javaFiles: number; resourceFiles: number };
export type ImportView = {
  projectId: string; importId: string; kind: string; title: string | null; filename: string; namespace: string; mcVersion: string;
  status: "building" | "ready" | "analysed" | "failed"; error: string | null; detection: Detection; deps: { id: string; name: string; licence: string }[]; ignored: string[];
  attestation: { textVersion: string; typedName: string; at: string; uploadSha256: string }; licence: { detected: string[]; claimed: string; effective: string; conflict: string | null };
  sharing: { allowed: false; reason: string }; scan: { profile: "attested"; summary: string | null; warnings: string[]; blocked: string[] } | null; modBuildId: string | null; quarantined: boolean; revisionStatus: string; createdAt: string;
};
type ListBody = { attestation: { text: string; textVersion: string }; limits: { maxUploadBytes: number }; versions: string[]; imports: ImportView[] };
export type ImportServer = { id: string; name: string; compatible: boolean; reason?: string };
const LICENCES = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause", "ISC", "Unlicense", "CC0-1.0", "MPL-2.0", "EPL-2.0", "LGPL-2.1", "LGPL-3.0", "GPL-2.0", "GPL-3.0", "AGPL-3.0", "LicenseRef-All-Rights-Reserved"];
const KINDS = [{ k: "source", t: "Source ZIP", s: "Gradle, Maven or plain" }, { k: "jar", t: "Plugin JAR", s: "analysis only" }, { k: "datapack", t: "Data pack", s: "pack.mcmeta" }, { k: "resourcepack", t: "Resource pack", s: "pack.mcmeta" }];
const RULES = ["Size under 25 MB", "5,000 entries max", "Names: no traversal, absolute or control chars", "No duplicate or case-only paths", "No symbolic links", "No encrypted or zip64 entries", "Compression ratio caps 40:1 / 100:1", "Nested archives 2 deep max"];

export function ImportMod({ servers }: { servers: ImportServer[] }) {
  const [list, setList] = useState<ListBody | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [sel, setSel] = useState<string | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [mcVersion, setMcVersion] = useState("");
  const [accepted, setAccepted] = useState(false);
  const [typedName, setTypedName] = useState("");
  const [licence, setLicence] = useState("");
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<{ text: string; problems?: string[] } | null>(null);
  const [server, setServer] = useState("");
  const [report, setReport] = useState<{ blocking?: unknown[]; findings?: { severity: string; message: string }[] } | null>(null);

  const load = useCallback(async () => {
    const r = await fetch("/api/cyrus/import", { cache: "no-store" });
    if (!r.ok) { setErr(r.status === 404 ? "Importing is not switched on for this account." : "Could not load your imports."); return; }
    const b = (await r.json()) as ListBody;
    setList(b); setMcVersion((v) => v || b.versions[0] || "");
    setSel((s) => s ?? b.imports[0]?.importId ?? null);
  }, []);
  useEffect(() => { void load(); }, [load]);
  const cur = list?.imports.find((i) => i.importId === sel) ?? null;
  useEffect(() => { // poll a running import
    if (!cur || cur.status !== "building") return;
    const t = window.setTimeout(() => void load(), 3000);
    return () => window.clearTimeout(t);
  }, [cur, load]);

  const upload = async () => {
    if (!file || !list) return;
    setBusy(true); setMsg(null);
    const f = new FormData();
    f.set("file", file); f.set("mcVersion", mcVersion); f.set("accepted", accepted ? "true" : "false"); f.set("typedName", typedName); f.set("textVersion", list.attestation.textVersion); if (licence) f.set("claimedLicence", licence);
    const r = await fetch("/api/cyrus/import", { method: "POST", body: f });
    const b = (await r.json().catch(() => ({}))) as { import?: ImportView; error?: string; problems?: string[]; unsupported?: string[] };
    setBusy(false);
    if (!r.ok || !b.import) { setMsg({ text: b.error ?? "The import was refused.", problems: [...(b.problems ?? []), ...(b.unsupported ?? [])] }); return; }
    setFile(null); setAccepted(false);
    await load(); setSel(b.import.importId);
  };
  const conflicts = async () => {
    if (!cur || !server) return;
    setBusy(true);
    const r = await fetch(`/api/cyrus/import/${cur.importId}/conflicts`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ serverId: server }) });
    const b = (await r.json().catch(() => ({}))) as { report?: { blocking?: unknown[]; findings?: { severity: string; message: string }[] }; error?: string };
