  const warns = cur?.scan?.warnings ?? [];
  const blocked = cur?.scan?.blocked ?? [];
  const step = (ok: boolean | null, label: string) => <span className={`st ${ok === null ? "" : ok ? "done" : "fail"}`}><i />{label}</span>;
  return (
    <StudioShell mod={null} trail={[{ label: "Import your mod", href: "/dashboard/cyrus/import" }]} current={cur?.title ?? cur?.detection.name ?? "New import"} studio={null} kind="import">
