                <label className="fg-field">File (.zip or .jar)<input className="fg-input" type="file" accept=".zip,.jar" onChange={(e) => setFile(e.target.files?.[0] ?? null)} /></label>
                <label className="fg-field">Minecraft<select className="fg-input" value={mcVersion} onChange={(e) => setMcVersion(e.target.value)}>{(list?.versions ?? []).map((v) => <option key={v} value={v}>{v}</option>)}</select></label>
                <div className="fg-field">Ownership</div>
                <p className="cys-hint" style={{ margin: 0 }}>{list?.attestation.text}</p>
                <label className="fg-ack"><input type="checkbox" checked={accepted} onChange={(e) => setAccepted(e.target.checked)} />I confirm the statement above</label>
                <label className="fg-field">Type your full name<input className="fg-input" value={typedName} maxLength={120} onChange={(e) => setTypedName(e.target.value)} /></label>
                <label className="fg-field">Licence<select className="fg-input" value={licence} onChange={(e) => setLicence(e.target.value)}><option value="">Use what the files say</option>{LICENCES.map((l) => <option key={l} value={l}>{l}</option>)}</select></label>
                <button type="button" className="cys-btn sm primary" disabled={busy || !file || !accepted || typedName.trim().length < 2} onClick={() => void upload()}>{busy ? "Uploading…" : "Import"}</button>
                {msg ? <div className="fg-err" role="alert">{msg.text}{msg.problems?.length ? <ul className="fg-list">{msg.problems.slice(0, 6).map((p, i) => <li key={i}>{p}</li>)}</ul> : null}</div> : null}
              </div>
            </section>
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">Safe ingestion</span></div>
              <div className="fg-body"><ul className="fg-list">{RULES.map((r) => <li key={r}>{r}</li>)}</ul><p className="cys-hint">Nothing is extracted to disk or run. Every rule is checked before anything is read.</p></div>
            </section>
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">Your imports</span><span className="n">{list?.imports.length ?? "…"}</span></div>
              <div className="fg-body">
                {list?.imports.length === 0 ? <p className="cys-hint">Nothing imported yet.</p> : null}
                {list?.imports.map((i) => <button key={i.importId} type="button" className={`fg-row ${sel === i.importId ? "on" : ""}`} onClick={() => { setSel(i.importId); setReport(null); }}><span className="tx"><b>{i.title ?? i.detection.name ?? i.filename}</b><small>{i.kind} · {i.mcVersion} · {i.status}</small></span></button>)}
              </div>
            </section>
          </div>

          <div className="fg-col">
            {!cur ? <section className="cys-panel cys-glass"><div className="fg-body" style={{ paddingTop: 14 }}><p className="cys-hint">Import a mod to see what Cyrus detected.</p></div></section> : (
              <>
                <section className="cys-panel cys-glass">
                  <div className="fg-steps">{step(true, "Upload")}<span className="sep" />{step(true, "Ownership")}<span className="sep" />{step(cur.status !== "failed" || !!d?.name, "Detected")}<span className="sep" />{step(cur.scan ? blocked.length === 0 : cur.status === "failed" ? false : null, "Scan")}<span className="sep" />{step(cur.status === "ready" ? true : cur.status === "failed" ? false : null, "Revision 0")}</div>
                </section>
                <section className="cys-panel cys-glass">
                  <div className="cys-ph"><span className="cys-eyebrow">Ownership</span><span className="cys-tag ok">Attested</span></div>
                  <div className="fg-body">
                    <dl className="fg-kv">
                      <dt>Attested by</dt><dd>{cur.attestation.typedName}</dd>
                      <dt>When</dt><dd>{new Date(cur.attestation.at).toLocaleString()}</dd>
                      <dt>Licence</dt><dd>{cur.licence.effective}{cur.licence.claimed ? ` (you said ${cur.licence.claimed})` : ""}</dd>
                      <dt>Upload</dt><dd>sha256 {cur.attestation.uploadSha256.slice(0, 12)}…</dd>
                      <dt>Sharing</dt><dd>private ({cur.sharing.reason})</dd>
                    </dl>
                    {cur.licence.conflict ? <div className="fg-banner"><span><b>Licence mismatch.</b> {cur.licence.conflict}</span></div> : null}
                  </div>
                </section>
                <section className="cys-panel cys-glass">
                  <div className="cys-ph"><span className="cys-eyebrow">Detected</span>{d?.sourcesComplete === true ? <span className="cys-tag ok">Complete sources</span> : d?.sourcesComplete === false ? <span className="cys-tag warn">Sources incomplete</span> : null}</div>
                  <div className="fg-body">
                    <dl className="fg-kv">
                      <dt>Kind</dt><dd>{cur.kind}{d?.descriptorFile ? ` · ${d.descriptorFile}` : ""}</dd>
                      <dt>Build</dt><dd>{d?.buildSystem ?? "none"} (read, not run)</dd>
                      <dt>Name</dt><dd>{d?.name ?? "?"} {d?.version ?? ""}</dd>
                      {d?.main ? <><dt>Main</dt><dd>{d.main}</dd></> : null}
                      {d?.apiVersion ? <><dt>api-version</dt><dd>{d.apiVersion}</dd></> : null}
                      <dt>Commands</dt><dd>{d?.commands.length ? d.commands.map((c) => `/${c}`).join(" · ") : "none"}</dd>
                      <dt>Permissions</dt><dd>{d?.permissions.length ?? 0}</dd>
                      <dt>Files</dt><dd>{d?.javaFiles ?? 0} source · {d?.resourceFiles ?? 0} resources</dd>
                    </dl>
                    <div className="fg-field">Dependencies</div>
                    {cur.deps.length ? cur.deps.map((x) => <div key={x.id} className="fg-card"><div className="hd"><b>{x.name}</b><span className="cys-tag ok">Allowlisted</span></div><span className="fg-mono">{x.licence} · compile-only, never shaded into your jar</span></div>) : <p className="cys-hint">None from the allowlist.</p>}
                    {d?.missingClasses.length ? <p className="cys-hint">Missing classes (not on the allowlist): {d.missingClasses.slice(0, 6).join(", ")}</p> : null}
                    {cur.ignored.length ? <p className="cys-hint">Kept out: {cur.ignored.slice(0, 6).join(", ")}</p> : null}
                  </div>
                </section>
                <section className="cys-panel cys-glass">
                  <div className="cys-ph"><span className="cys-eyebrow">Scan</span>{cur.scan ? <span className={`cys-tag ${blocked.length ? "bad" : "warn"}`}>{blocked.length ? `${blocked.length} blocked` : `${warns.length} warning${warns.length === 1 ? "" : "s"}`}</span> : <span className="cys-tag dim">Not run</span>}</div>
                  <div className="fg-body">
                    {cur.scan ? <div className={`fg-banner ${blocked.length ? "bad" : ""}`}><span><b>Checked with the attested profile{cur.scan.summary ? `: ${cur.scan.summary}` : ""}.</b> Nxeon checked this code but does not guarantee that it is safe. Code you own may use what Cyrus&apos;s own code may not.</span></div> : <p className="cys-hint">{cur.status === "building" ? "Building and scanning…" : "No scan result."}</p>}
                    {[...blocked.map((b) => ({ b: true, t: b })), ...warns.map((w) => ({ b: false, t: w }))].slice(0, 30).map((x, i) => <div key={i} className="fg-ack" style={{ color: x.b ? "var(--bad)" : "var(--warn)" }}>{x.b ? "Blocked:" : "Warning:"} <span style={{ color: "var(--ink-2)" }}>{x.t}</span></div>)}
                    {cur.error ? <p className="fg-err">{cur.error}</p> : null}
                  </div>
                </section>
              </>
            )}
          </div>

          <div className="fg-col">
            {cur ? (
              <>
                <section className="cys-panel cys-glass">
                  <div className="cys-ph"><span className="cys-eyebrow">Revision 0</span><span className={`cys-tag ${cur.status === "ready" ? "ok" : cur.status === "failed" ? "bad" : "dim"}`}>{cur.status}</span></div>
                  <div className="fg-body">
                    <p className="fg-h1" style={{ fontSize: 15 }}>{cur.title ?? d?.name ?? cur.filename}</p>
                    <p className="fg-mono">project {cur.namespace} · private</p>
                    <ul className="fg-list"><li>Your names are kept; new ids use {cur.namespace}</li>{cur.kind === "jar" ? <li>Jar-only: analysis and diagnosis only; Cyrus cannot change it</li> : null}</ul>
                  </div>
                </section>
                <section className="cys-panel cys-glass">
                  <div className="cys-ph"><span className="cys-eyebrow">Before you install</span></div>
                  <div className="fg-body">
                    <ul className="fg-list">
                      <li>Test Flight · {cur.mcVersion}<span className="r">NOT RUN</span></li>
                      <li>Conflicts with a server<span className="r">{report ? (report.blocking?.length ? `${report.blocking.length} BLOCKING` : "CHECKED") : "NOT CHECKED"}</span></li>
                      <li>Real game client<span className="r">NOT VERIFIED</span></li>
                    </ul>
                    <div className="fg-pills fg-edit">
                      <select className="fg-input" aria-label="Server" value={server} onChange={(e) => setServer(e.target.value)} style={{ flex: 1 }}><option value="">Pick a server…</option>{servers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select>
                      <button type="button" className="cys-btn sm" disabled={!server || busy || !cur.modBuildId} onClick={() => void conflicts()}>Check a server</button>
                    </div>
                    {report?.findings?.length ? <ul className="fg-list">{report.findings.slice(0, 8).map((f, i) => <li key={i}><span className={`cys-tag ${f.severity === "blocking" ? "bad" : f.severity === "warn" ? "warn" : "dim"}`}>{f.severity}</span>{f.message}</li>)}</ul> : null}
                  </div>
                </section>
              </>
            ) : null}
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">What Cyrus sees</span></div>
              <div className="fg-body"><p className="cys-hint" style={{ margin: 0 }}>Your README and LICENSE reach Cyrus only as quoted data, never as instructions, and never go into the jar or shared knowledge. Change builds follow your plan: tokens, the models it allows and the asset gates.</p></div>
            </section>
            <p className="fg-ro cys-hint">Read-only on a phone: import from a larger screen.</p>
          </div>
        </div>
      )}
    </StudioShell>
  );
}

