"use client";
// Cyrus r31: Data packs + worldgen studio (/dashboard/cyrus/<id>/studio/datapacks), over GET /api/cyrus/datapacks/v1
// (CYRUS_DATAPACK_STUDIO) and the delivery status read model (GET /api/cyrus/delivery/v1, CYRUS_DELIVERY). Follows the
// v2 mockup datapack-studio.html, which the owner has NOT reviewed yet. READ-ONLY on every width: the spec is
// re-validated and re-emitted per version by the server; changes go through a change build. Per-version status,
// the restart banner (world generation / registry content), and the honest delivery states incl. rollback.
import { useEffect, useMemo, useState } from "react";
import type { DatapackStudioView, PackView } from "@/lib/cyrus/datapack/studio-view";
import { StudioShell, type StudioMod } from "../studios/StudioShell";
import "./forge.css";

type Delivery = { jobId: string; serverId: string | null; op: string | null; subject: { buildId?: string; projectId?: string }; state: string; pending: boolean; ok: boolean | null; headline: string; needsAttention: boolean; rollback: { ok: boolean; restored: number; removed: number; restarted: boolean; cameBackHealthy: boolean | null } | null; keptWorldFolders: string[]; createdAt: string };
const WORLDGEN = new Set(["dimension_type", "dimension", "biome", "configured_feature", "placed_feature", "structure", "structure_set", "structure_template", "noise_settings", "configured_carver"]);
const LABEL: Record<string, string> = { recipe: "Recipes", loot_table: "Loot tables", advancement: "Advancements", tag: "Tags", function: "Functions", enchantment: "Enchantments", predicate: "Predicates", item_modifier: "Item modifiers", dimension_type: "Dimension types", dimension: "Dimensions", biome: "Biomes", configured_feature: "Features", placed_feature: "Placed features", structure: "Structures", structure_set: "Structure sets", structure_template: "Structure templates", noise_settings: "Noise settings", configured_carver: "Carvers" };
const STATE: Record<string, { tag: string; text: string }> = {
  delivered: { tag: "ok", text: "Delivered" }, updated: { tag: "ok", text: "Updated" }, removed: { tag: "ok", text: "Removed" },
  rolled_back: { tag: "warn", text: "Rolled back" }, rollback_incomplete: { tag: "bad", text: "Rollback incomplete" },
  refused: { tag: "dim", text: "Refused" }, failed: { tag: "bad", text: "Failed" }, queued: { tag: "dim", text: "Queued" }, running: { tag: "acc", text: "Running" },
};

function flat(o: unknown, prefix = "", out: [string, string][] = [], depth = 0): [string, string][] {
  if (o && typeof o === "object" && !Array.isArray(o) && depth < 3) { for (const [k, v] of Object.entries(o as Record<string, unknown>)) flat(v, prefix ? `${prefix}.${k}` : k, out, depth + 1); }
  else out.push([prefix, typeof o === "string" ? o : JSON.stringify(o)]);
  return out;
}

export function DataPacks({ mod }: { mod: StudioMod }) {
  const [view, setView] = useState<DatapackStudioView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [pi, setPi] = useState(0);
  const [res, setRes] = useState(0);
  const [ver, setVer] = useState<string | null>(null);
  const [tab, setTab] = useState<"form" | "json">("form");
  const [deliveries, setDeliveries] = useState<Delivery[] | null>(null);
  useEffect(() => {
    fetch(`/api/cyrus/datapacks/v1?root=${encodeURIComponent(mod.rootId)}`, { cache: "no-store" }).then(async (r) => {
      if (!r.ok) { setErr(r.status === 404 ? "The Data Pack Studio is not switched on." : "Could not load the data packs."); return; }
      const v = (await r.json()) as DatapackStudioView;
      setView(v); setVer(v.mcVersion);
      const d = await fetch("/api/cyrus/delivery/v1?limit=20", { cache: "no-store" }).catch(() => null);
      if (d?.ok) { const b = (await d.json()) as { deliveries?: Delivery[] }; setDeliveries((b.deliveries ?? []).filter((x) => (x.subject.buildId && v.buildIds.includes(x.subject.buildId)) || (v.projectId && x.subject.projectId === v.projectId))); }
      else setDeliveries(null);
    }).catch(() => setErr("Could not load the data packs."));
  }, [mod.rootId]);

  const pack: PackView | null = view?.packs[pi] ?? null;
  const groups = useMemo(() => {
    const g = new Map<string, { i: number; id: string }[]>();
    (pack?.resources ?? []).forEach((r, i) => g.set(r.type, [...(g.get(r.type) ?? []), { i, id: r.id }]));
    return [...g.entries()].sort((a, b) => Number(WORLDGEN.has(a[0])) - Number(WORLDGEN.has(b[0])) || (a[0] < b[0] ? -1 : 1));
  }, [pack]);
  const r = pack?.resources[res] ?? null;
  const pv = pack?.versions.find((v) => v.version === ver) ?? pack?.versions[0] ?? null;
  const restart = pack ? pack.versions.some((v) => v.apply === "restart") || pack.worldgen : false;
  const ns = view?.namespace ?? "";
  const dims = (pack?.resources ?? []).filter((x) => x.type === "dimension").map((x) => x.id);

  return (
    <StudioShell mod={mod} current="Data Pack Studio" studio={null} kind="datapacks">
      {err ? <div className="cys-empty" style={{ margin: "auto" }}><p>{err}</p></div> : !view ? <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading data packs…</div> : !view.packs.length ? <div className="cys-empty" style={{ margin: "auto" }}><p>This mod has no data pack yet. Ask Cyrus for recipes, loot, advancements or a new dimension in a change build.</p></div> : (
        <div className="fg-ws">
          <div className="fg-col">
            <section className="cys-panel cys-glass cys-hairline">
              <div className="cys-ph"><span className="cys-eyebrow">{pack?.name}</span><span className="cys-tag dim">{ns}</span></div>
              {view.packs.length > 1 ? <div className="fg-body"><select className="fg-input" aria-label="Pack" value={pi} onChange={(e) => { setPi(Number(e.target.value)); setRes(0); }}>{view.packs.map((p, i) => <option key={p.name} value={i}>{p.name}</option>)}</select></div> : null}
              <nav className="fg-tree" aria-label="Pack contents">
                {groups.map(([type, items], gi) => (
                  <div key={type}>
                    {gi > 0 && WORLDGEN.has(type) && !WORLDGEN.has(groups[gi - 1][0]) ? <div className="grp" style={{ paddingTop: 14 }}><span className="cys-eyebrow">Worldgen</span><span className="cys-tag warn">Restart</span></div> : null}
                    <div className="grp">{LABEL[type] ?? type}<span className="n">{items.length}</span></div>
                    {items.map((x) => <button key={x.i} type="button" className={`${res === x.i ? "on" : ""} ${pv && !pv.ok ? "bad" : ""}`} onClick={() => setRes(x.i)}>{x.id}</button>)}
                  </div>
                ))}
              </nav>
            </section>
          </div>

          <div className="fg-col">
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">{r ? (LABEL[r.type] ?? r.type).replace(/s$/, "") : ""}</span><b style={{ fontSize: 15 }}>{r?.id}</b><span className="fg-mono">{ns}:{r?.id}</span><span style={{ flex: 1 }} />
                <div className="fg-tabs" role="tablist"><button type="button" role="tab" aria-selected={tab === "form"} className={tab === "form" ? "on" : ""} onClick={() => setTab("form")}>Form</button><button type="button" role="tab" aria-selected={tab === "json"} className={tab === "json" ? "on" : ""} onClick={() => setTab("json")}>Spec JSON</button></div>
              </div>
              <div className="fg-body">
                <div className="fg-vstrip" role="group" aria-label="Versions">
                  {pack?.versions.map((v) => <button key={v.version} type="button" className={`fg-vchip ${pv?.version === v.version ? "on" : ""}`} onClick={() => setVer(v.version)} title={v.ok ? `${v.files} files` : v.errors[0]}>{v.version}<span className="fg-dots"><span className={v.ok ? "ok" : "bad"} /><span className={v.ok ? "ok" : "bad"} /><span /></span></button>)}
                </div>
                <p className="fg-mono" style={{ margin: 0 }}>{pv?.ok ? "generated · validated" : "not valid for this version"} · loaded in a real server: {deliveries?.some((d) => d.ok) ? "see Deliveries" : "not run for this pack"}</p>
                {restart ? (
                  <div className="fg-banner" role="note"><span><b>Restart required{pack?.worldgen ? ". New chunks only." : "."}</b> {pack?.worldgen ? <>World generation loads when the server starts; Nxeon restarts once after install.{dims.length ? <> Players reach {dims.length === 1 ? "the dimension" : "the dimensions"} with <span className="fg-mono">/{ns} tp</span> (no portal), and {dims.length === 1 ? "it exists" : "they exist"} only after that restart.</> : null} Existing chunks keep their old terrain.</> : "Enchantments are registry content: they load only when the server starts."}{!view.worldgenOn && pack?.worldgen ? " World generation is not switched on yet, so this pack is refused." : ""}</span></div>
                ) : <div className="fg-banner ok"><span><b>No restart.</b> This pack loads with /reload.</span></div>}
                {r ? (tab === "json" ? <pre className="fg-pre">{JSON.stringify(r.json, null, 2)}</pre> : (
                  <div className="fg-grid4">{flat(r.json).filter(([k]) => k !== "type" && k !== "id").slice(0, 40).map(([k, v]) => <label key={k} className="fg-field">{k}<input className="fg-input" readOnly value={v.length > 80 ? `${v.slice(0, 80)}…` : v} /></label>)}</div>
                )) : null}
                <p className="cys-hint" style={{ margin: 0 }}>Read-only here: to change {r?.id ?? "the pack"}, ask Cyrus in a change build. The server re-checks every version, it never trusts the stored result.</p>
              </div>
            </section>
          </div>

          <div className="fg-col">
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">Checks</span><span className="cys-tag dim">{pv?.version}</span></div>
              <div className="fg-body">
                {pv ? <div className={`fg-banner ${pv.ok ? "ok" : "bad"}`}><span><b>{pv.ok ? `Valid for ${pv.version}` : `Not valid for ${pv.version}`}</b> {pv.ok ? `${pv.files} files re-emitted for the exact version.` : pv.errors.slice(0, 2).join(" · ")}</span></div> : null}
                <ul className="fg-list">{(pv?.checks ?? []).map((c) => <li key={c.id}><span className="fg-mono" style={{ color: "var(--ink)" }}>{c.id}</span><span className="r" style={{ color: c.status === "pass" ? "var(--ok)" : c.status === "fail" ? "var(--bad)" : c.status === "warn" ? "var(--warn)" : undefined }}>{c.status === "not_run" ? "not run" : c.status}</span></li>)}</ul>
                {pv?.warnings.length ? <ul className="fg-list">{pv.warnings.map((w, i) => <li key={i} style={{ color: "var(--warn)" }}>{w}</li>)}</ul> : null}
              </div>
            </section>
            <section className="cys-panel cys-glass">
              <div className="cys-ph"><span className="cys-eyebrow">Deliveries</span><span className="n">{deliveries?.length ?? "–"}</span></div>
              <div className="fg-body">
                {deliveries === null ? <p className="cys-hint">Delivery status is not available (sending to servers is not switched on).</p> : !deliveries.length ? <p className="cys-hint">Not sent to a server yet.</p> : deliveries.map((d) => {
                  const s = STATE[d.state] ?? { tag: "dim", text: d.state };
                  return (
                    <div key={d.jobId} className={`fg-card ${d.needsAttention ? "bad" : d.state === "rolled_back" ? "warn" : ""}`}>
                      <div className="hd"><span className={`cys-tag ${s.tag}`}>{s.text}</span><b>{d.headline}</b></div>
                      {d.rollback ? <span className="fg-mono">rollback: {d.rollback.restored} restored · {d.rollback.removed} removed · {d.rollback.cameBackHealthy === null ? "health not checked" : d.rollback.cameBackHealthy ? "came back healthy" : "did NOT come back healthy"}</span> : null}
                      {d.needsAttention ? <span className="fg-err">The server may not be exactly as it was. Contact support.</span> : null}
                      {d.keptWorldFolders.length ? <span className="fg-mono">kept world folders: {d.keptWorldFolders.join(", ")}</span> : null}
                    </div>
                  );
                })}
              </div>
            </section>
          </div>
        </div>
      )}
    </StudioShell>
  );
}

