import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".shots/tokens.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch({ args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"] });
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const path = (who, q = "") => `/dashboard/cyrus/${tok[who].buildId}/studio/model${q}`;

const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;
async function shot(name, who, url, { view = "desktop", theme = "dark", act } = {}) {
  if (ONLY && !ONLY.some((o) => name.includes(o))) return;
  const v = VIEW[view];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: tok[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(BASE + url, { waitUntil: "load", timeout: 300000 }).catch((e) => errs.push("goto " + e));
  await page.waitForSelector(".ms-hdr, .ms-ncard", { timeout: 180000 }).catch((e) => errs.push("wait " + String(e).slice(0, 80)));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 1000 }).catch(() => {}); }
  await page.waitForTimeout(2500);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(1200);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png`, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}

