cat > scripts/cyrus/forge-shots.mjs <<'EOF'
// Cyrus r31 screenshots: Mod Packs, Import your mod, Data packs (run ON node-2 against `devhost dev`). Not part of the app.
//   devhost run -- node scripts/cyrus/forge-shots.mjs   (env: BASE, TOKENS, FX, OUT, UPLOAD)
// Writes <OUT>/{packs,import,datapack}-*.png and prints page errors + horizontal overflow per shot.
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots";
const tok = JSON.parse(readFileSync(process.env.TOKENS, "utf8"));
const fx = JSON.parse(readFileSync(process.env.FX, "utf8"));
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;
async function shot(name, url, { view = "desktop", theme = "dark", wait = ".fg-ws, .cys-empty", act, full = false } = {}) {
  if (ONLY && !ONLY.some((o) => name.includes(o))) return;
  const v = VIEW[view];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: tok.all.token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(BASE + url, { waitUntil: "load", timeout: 300000 }).catch((e) => errs.push("goto " + e));
  await page.waitForSelector(wait, { timeout: 180000 }).catch((e) => errs.push("wait " + String(e).slice(0, 80)));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 1000 }).catch(() => {}); }
  await page.waitForTimeout(1500);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(1200);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: full, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}
const compose = async (page) => {
  await page.getByLabel("Name").fill("Guild Survival");
  for (const n of ["Void Arsenal", "Guild Craft", "Shop Plus"]) await page.getByLabel(n).check();
  await page.getByRole("button", { name: "Check conflicts" }).click();
  await page.waitForSelector(".fg-card", { timeout: 60000 });
};
const save = async (page) => { await compose(page); await page.getByRole("button", { name: "Save pack" }).click(); await page.waitForTimeout(2500); };
const upload = (file) => async (page) => {
  await page.setInputFiles('input[type="file"]', file);
  await page.getByLabel("I confirm the statement above").check();
  await page.getByLabel("Type your full name").fill("Alex Example");
  await page.getByRole("button", { name: "Import", exact: true }).click();
  await page.waitForTimeout(4000);
};
const dp = `/dashboard/cyrus/${fx.datapacks}/studio/datapacks`;
const biome = async (page) => { const b = page.locator(".fg-tree button", { hasText: "crystal_plains" }); if (await b.count()) await b.first().click(); };
await shot("packs-dark", "/dashboard/cyrus/packs", { act: compose });
await shot("packs-saved-dark", "/dashboard/cyrus/packs", { act: save });
await shot("packs-light", "/dashboard/cyrus/packs", { theme: "light", act: compose });
await shot("packs-narrow", "/dashboard/cyrus/packs", { view: "phone", full: true });
await shot("import-empty-dark", "/dashboard/cyrus/import");
await shot("import-dark", "/dashboard/cyrus/import", { act: upload(process.env.UPLOAD) });
await shot("import-light", "/dashboard/cyrus/import", { theme: "light" });
await shot("import-narrow", "/dashboard/cyrus/import", { view: "phone", full: true });
await shot("datapack-dark", dp, { act: biome });
await shot("datapack-json-dark", dp, { act: async (p) => { await biome(p); await p.getByRole("tab", { name: "Spec JSON" }).click(); } });
await shot("datapack-plain-dark", dp, { act: async (p) => { await p.selectOption('select[aria-label="Pack"]', { index: 1 }).catch(() => {}); } });
await shot("datapack-light", dp, { theme: "light", act: biome });
await shot("datapack-narrow", dp, { view: "phone", full: true });
await browser.close();
EOF
echo ok

