// Cyrus r31 screens: the Data Pack + worldgen studio read model (lib/cyrus/datapack/studio-view.ts). Fails closed (switch
// off / no viewer / not the owner = 404), re-validates every stored spec per version, never trusts the stored result.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { handleDatapackView, hasWorldgenSpec, packView, type DatapackViewDeps } from "../lib/cyrus/datapack/studio-view";
import { DATAPACK_VERSIONS } from "../lib/cyrus/datapack/versions";
import type { AssetRow, ChainInfo } from "../lib/cyrus/studios/service";

const NS = "nx_worldg01";
const showcase = () => JSON.parse(readFileSync(path.join(__dirname, "fixtures/cyrus-worldgen/showcase.json"), "utf8"));
const row = (spec: unknown, key = "crystal_realm", at = 1): AssetRow => ({ id: `as${key}${at}`, projectId: "cp1", revisionId: "rev1", assetKey: key, kind: "datapack", sha256: "0".repeat(64), size: 1, origin: "generated", mime: null, path: null, provenance: { spec }, createdAt: new Date(at * 1000) });
const chain: ChainInfo = { rootBuildId: "mb1", latestBuildId: "mb1", mcVersion: "1.21.11", pluginName: "Frost", assets: null, candidateBuilds: [] };
function deps(o: Partial<DatapackViewDeps> = {}, rows: AssetRow[] = [row(showcase())]): DatapackViewDeps {
  return {
    on: () => true, worldgenOn: () => true, viewer: async () => ({ userId: "u1" }),
    chain: async (u, r) => (u === "u1" && r === "mb1" ? chain : null),
    store: { projectForRoot: async () => ({ id: "cp1", userId: "u1", namespace: NS, rootBuildId: "mb1", headRevisionId: null, title: null }), assets: async () => rows },
    buildIds: async () => ["mb1", "mb2"], rateLimit: () => ({ ok: true }), ...o,
  };
}
const get = (d: DatapackViewDeps, root = "mb1") => handleDatapackView(new Request(`http://x/api/cyrus/datapacks/v1?root=${root}`), d);

describe("r31 data pack studio read model", () => {
  it("re-validates and re-emits the stored spec for every data pack version; worldgen means restart", async () => {
    const r = await get(deps());
    assert.equal(r.status, 200);
    const v = await r.json();
    assert.equal(v.packs.length, 1);
    const p = v.packs[0];
    assert.equal(p.worldgen, true);
    assert.deepEqual(p.versions.map((x: { version: string }) => x.version), [...DATAPACK_VERSIONS]);
    const cur = p.versions.find((x: { version: string }) => x.version === "1.21.11");
    assert.equal(cur.ok, true); assert.equal(cur.apply, "restart"); assert.ok(cur.files > 0);
    assert.ok(cur.checks.some((c: { id: string; status: string }) => c.id === "worldgen" && c.status === "pass"));
    assert.deepEqual(v.buildIds, ["mb1", "mb2"]);
  });
  it("worldgen switched off: the same spec is refused (fail closed), never shown as valid", () => {
    const p = packView(row(showcase()), NS, false)!;
    assert.ok(p.versions.every((x) => !x.ok));
  });
  it("the newest row per pack wins; rows without a spec are ignored", async () => {
    const old = { ...showcase(), description: "old" }, cur = { ...showcase(), description: "new" };
    const v = await (await get(deps({}, [row(old, "crystal_realm", 1), row(cur, "crystal_realm", 5), { ...row(null, "nospec", 9), provenance: {} }]))).json();
    assert.equal(v.packs.length, 1); assert.equal(v.packs[0].description, "new");
    assert.equal(hasWorldgenSpec({ resources: [{ type: "recipe", id: "x" }] }), false);
  });
  it("fails closed: switch off, no viewer, another person's mod, a bad root", async () => {
    assert.equal((await get(deps({ on: () => false }))).status, 404);
    assert.equal((await get(deps({ viewer: async () => null }))).status, 404);
    assert.equal((await get(deps({ viewer: async () => ({ userId: "u2" }) }))).status, 404);
    assert.equal((await get(deps(), "../x")).status, 400);
    assert.equal((await get(deps({ rateLimit: () => ({ ok: false, retryAfterSec: 3 }) }))).status, 429);
    const notMine = await (await get(deps({ store: { projectForRoot: async () => ({ id: "cp1", userId: "u9", namespace: NS, rootBuildId: "mb1", headRevisionId: null, title: null }), assets: async () => { throw new Error("must not read"); } } }))).json();
    assert.deepEqual(notMine.packs, []);
  });
});
EOF
