export const catalogToolsOn = (): boolean => process.env.CYRUS_CATALOG_TOOLS === "1";

let indexPromise: { file: string; p: Promise<CatalogIndex | null> } | null = null;
/** The configured index, opened once per process. Any failure = null (fail closed, never throws). */
export function configuredCatalogIndex(): Promise<CatalogIndex | null> {
  const file = process.env.CYRUS_CATALOG_INDEX || "";
  if (!file || !existsSync(file)) return Promise.resolve(null);
  if (indexPromise?.file !== file) {
    indexPromise = {
      file,
      p: import("./sqlite-index").then((m) => m.createSqliteCatalogIndex(file)).then(async (ix) => ((await ix.size()) > 0 ? ix : null)).catch(() => null),
    };
  }
  return indexPromise.p;
}

