// Cyrus r31: the studio LIBRARY BROWSER over the catalog index (a person browsing, not the model's catalog_search tool).
//   GET  /api/cyrus/library/v2/browse?q=&kind=&tier=&fit=minecraft&minQuality=&offset=   -> rows + facets + the plan gate
//   POST /api/cyrus/library/v2/use { ref: "cat:<sha256>", projectId, slotId, purpose? }     -> "Use in project" (libraryRef)
// The SAME gate as the build tools (./tools.ts access(): plan -> kinds, licence tiers per plan, proprietary clearance),
// applied server side on every request; locked kinds are listed with what unlocks them, never returned as rows. Only
// published entries. "Use in project" goes through the backend's useCatalogAsset (the plan gate again, the project's own
// copy, the use record a takedown marks); the host injects it, absent = 503 (honest: not wired here).
// HOST SEAM: no Nxeon imports; viewer, plan, index, the use function and the rate limit are injected. Fails closed.
import { canAsset } from "../../engine-core/asset-gate";
import { CATALOG_KINDS, CATALOG_REF_RE, LICENCE_TIERS, gateKindOf, type CatalogEntry, type CatalogKind, type LicenceTier } from "./entry";
import type { CatalogIndex } from "./retrieval";
import { access } from "./tools";

export const LIBRARY_BROWSE_FLAG = "CYRUS_LIBRARY_BROWSE";
export const BROWSE_PAGE = 24;
export type BrowseRow = {
  ref: string; id: string; kind: CatalogKind; title: string; description: string; tags: string[]; tier: LicenceTier; spdx: string | null; attribution: string | null;
  quality: number; fit: { fit: string; reason: string | null } | null; tech: { format: string | null; bytes: number | null; triangles: number | null; width: number | null; durationS: number | null };
  contributed: boolean; variants: number;
};
export type LockedKind = { kind: CatalogKind; needs: string | null };
export type BrowseResult = { total: number; offset: number; rows: BrowseRow[]; plan: string; kinds: CatalogKind[]; tiers: LicenceTier[]; locked: LockedKind[]; notice: string | null };

export type UseRequest = { userId: string; ref: string; projectId: string; slotId: string; purpose?: string; plan: unknown };
export type UseResponse = { ok: true; slot: unknown; copied: boolean; reused: boolean; rule: string | null } | { ok: false; code: string; reason: string };
export type BrowseDeps = {
  on(): boolean;
  viewer(): Promise<{ userId: string } | null>;
  planOf(userId: string): Promise<unknown>;
  index(): Promise<CatalogIndex | null>;
  proprietaryCleared: boolean;
  /** the project is the viewer's own */
  ownsProject(userId: string, projectId: string): Promise<boolean>;
  /** "Use in project"; absent = the backend is not wired (503) */
  use?: (r: UseRequest) => Promise<UseResponse>;
  rateLimit(key: string, max: number, windowMs: number): { ok: boolean; retryAfterSec?: number };
};

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "x-robots-tag": "noindex" } });
const NOT_FOUND = () => json(404, { error: "Not found" });

export function rowOf(e: CatalogEntry, game: string | null, groupSize = 1): BrowseRow {
  const g = game ? e.games[game] : undefined;
  return {
    ref: `cat:${e.id}`, id: e.id, kind: e.kind, title: e.title, description: e.shortDescription, tags: e.tags.slice(0, 8), tier: e.licence.tier, spdx: e.licence.spdx ?? null, attribution: e.licence.attribution ?? null,
    quality: e.quality.score, fit: g ? { fit: g.fit, reason: g.reason ?? null } : null,
    tech: { format: e.tech.format ?? null, bytes: e.tech.bytes ?? null, triangles: e.tech.triangles ?? null, width: e.tech.width ?? null, durationS: e.tech.durationS ?? null },
    contributed: e.licence.tier === "user-contributed", variants: groupSize,
  };
}

/** Pure over the injected index: the gated page. */
export async function browseCatalog(q: { text?: string; kind?: string | null; tier?: string | null; game?: string | null; fitOnly?: boolean; minQuality?: number; offset?: number }, ctx: { index: CatalogIndex; plan: unknown; proprietaryCleared: boolean }): Promise<BrowseResult> {
  const a = access(ctx.plan, ctx.proprietaryCleared);
  const locked: LockedKind[] = CATALOG_KINDS.filter((k) => !a.kinds.includes(k)).map((k) => { const d = canAsset(a.plan ?? "free", gateKindOf(k), "create"); return { kind: k, needs: d.ok ? null : (d.needs ?? null) }; });
  const base = { total: 0, offset: 0, rows: [] as BrowseRow[], plan: a.plan ?? "unknown", kinds: a.kinds, tiers: a.tiers, locked };
  if (!a.plan) return { ...base, notice: "Your plan could not be checked right now, so library assets cannot be picked." };
  if (!a.kinds.length || !a.tiers.length) return { ...base, notice: "Your plan cannot use library assets. Sounds need Saka or above; textures, models and motion need All models." };
  let kinds = a.kinds;
  if (q.kind) {
    if (!(CATALOG_KINDS as readonly string[]).includes(q.kind)) return { ...base, notice: "Unknown kind." };
    if (!a.kinds.includes(q.kind as CatalogKind)) return { ...base, notice: `${q.kind} assets are locked on your plan${locked.find((l) => l.kind === q.kind)?.needs ? ` (needs ${locked.find((l) => l.kind === q.kind)!.needs})` : ""}.` };
    kinds = [q.kind as CatalogKind];
  }
  let tiers = a.tiers;
  if (q.tier) {
    if (!(LICENCE_TIERS as readonly string[]).includes(q.tier) || !a.tiers.includes(q.tier as LicenceTier)) return { ...base, notice: "That licence tier is not available on your plan." };
    tiers = [q.tier as LicenceTier];
  }
  const offset = Math.max(0, Math.min(2000, Math.floor(q.offset ?? 0)));
  const text = (q.text ?? "").trim().slice(0, 120);
  const r = await ctx.index.search({ ...(text.length >= 2 ? { text } : {}), kinds, game: q.game ?? null, minQuality: Math.max(0, Math.min(100, q.minQuality ?? 0)), tiers, statuses: ["published"], includeNoFit: !q.fitOnly, limit: BROWSE_PAGE, offset });
  return { ...base, total: r.total, offset, rows: r.hits.map((h) => rowOf(h.entry, q.game ?? null, h.groupSize)), notice: null };
}

/** GET /api/cyrus/library/v2/browse */
export async function handleBrowse(req: Request, deps: BrowseDeps): Promise<Response> {
  if (!deps.on()) return NOT_FOUND();
  const v = await deps.viewer().catch(() => null);
  if (!v) return NOT_FOUND();
  const rl = deps.rateLimit(`cyrus:library:browse:${v.userId}`, 90, 60_000);
  if (!rl.ok) return json(429, { error: `Too many searches. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  const index = await deps.index().catch(() => null);
  if (!index) return json(503, { error: "The asset library is not available right now.", code: "index_unavailable" });
  const u = new URL(req.url).searchParams;
  const game = u.get("game");
  try {
    const plan = await deps.planOf(v.userId).catch(() => null);
    const r = await browseCatalog({ text: u.get("q") ?? "", kind: u.get("kind"), tier: u.get("tier"), game: game && /^[a-z][a-z0-9-]{1,31}$/.test(game) ? game : "minecraft", fitOnly: u.get("fit") === "1", minQuality: Number(u.get("minQuality") ?? 0) || 0, offset: Number(u.get("offset") ?? 0) || 0 }, { index, plan, proprietaryCleared: deps.proprietaryCleared });
    return json(200, r);
  } catch (e) {
    console.error("[cyrus-library] browse:", (e as Error).message);
    return json(500, { error: "Something went wrong on our side.", code: "server_error" });
  }
}

/** POST /api/cyrus/library/v2/use: "Use in project" (a ModSpec library slot with libraryRef + the project's copy). */
export async function handleUse(req: Request, deps: BrowseDeps): Promise<Response> {
  if (!deps.on()) return NOT_FOUND();
  const v = await deps.viewer().catch(() => null);
  if (!v) return NOT_FOUND();
  const rl = deps.rateLimit(`cyrus:library:use:${v.userId}`, 20, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  let b: Record<string, unknown>;
  try { b = (await req.json()) as Record<string, unknown>; } catch { return json(400, { error: "Send a JSON body.", code: "bad_body" }); }
  const ref = typeof b.ref === "string" && CATALOG_REF_RE.test(b.ref) ? b.ref : null;
  const projectId = typeof b.projectId === "string" && /^cp[0-9a-f]{20}$|^[A-Za-z0-9_-]{4,64}$/.test(b.projectId) ? b.projectId : null;
  const slotId = typeof b.slotId === "string" && /^[a-z][a-z0-9_]{1,31}$/.test(b.slotId) ? b.slotId : null;
  if (!ref || !projectId || !slotId) return json(400, { error: "ref (cat:<sha256>), projectId and slotId (lowercase letters, digits, _) are required.", code: "bad_request" });
  if (!(await deps.ownsProject(v.userId, projectId).catch(() => false))) return NOT_FOUND();
  if (!deps.use) return json(503, { error: "Using library assets in a project is not switched on yet.", code: "use_unavailable" });
  const plan = await deps.planOf(v.userId).catch(() => null);
  const r = await deps.use({ userId: v.userId, ref, projectId, slotId, purpose: typeof b.purpose === "string" ? b.purpose.slice(0, 300) : undefined, plan });
  if (!r.ok) return json(r.code === "asset_locked" || r.code === "tier_locked" ? 403 : r.code === "not_found" || r.code === "not_published" ? 404 : r.code === "bytes_unavailable" ? 503 : 409, { error: r.reason, code: r.code });
  return json(200, r);
}

