// Cyrus r31: the project's OWN copy of a library asset ("Use in project"). Bytes go to
// <NXEON_MODBUILD_DIR>/cyrus-projects/<projectId>/library/<sha256> (0600, content-addressed); the pick is recorded as a
// new "asset" revision with one asset row (key lib_<slotId>, origin library, provenance: libraryRef + licence), so the
// mod keeps building from this copy even after a takedown. Idempotent per (project, slot, sha256).
import { createHash } from "node:crypto";
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { cyrusConfig } from "../../config";
import type { StudioStore } from "../../studios/service";
import type { ProjectAssetSink } from "../backend/use";

export function fileProjectSink(store: StudioStore, root = path.join(cyrusConfig().modbuildDir, "cyrus-projects")): ProjectAssetSink {
  return {
    async put(a) {
      const sha256 = createHash("sha256").update(a.bytes).digest("hex");
      const key = `lib_${a.slotId}`;
      const rel = `library/${sha256}`;
      const rows = await store.assets(a.projectId);
      if (rows.some((r) => r.assetKey === key && r.sha256 === sha256)) return { sha256, path: rel };
      const dir = path.join(root, a.projectId, "library");
      await mkdir(dir, { recursive: true, mode: 0o700 });
      await writeFile(path.join(dir, sha256), a.bytes, { mode: 0o600 });
      const revs = await store.revisions(a.projectId);
      const head = revs.length ? revs[revs.length - 1] : null;
      const manifest = [...(head?.manifest ?? []).filter((e) => e.path !== `assets/library/${a.slotId}`), { path: `assets/library/${a.slotId}`, sha256, role: "asset" as const }];
      const rev = await store.addRevision(a.projectId, { kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null, engine: { toolchain: "cyrus-library-use 1" }, message: `Added ${a.slotId} from the asset library` });
      await store.recordAsset(a.projectId, { revisionId: rev.id, assetKey: key, kind: a.kind, sha256, size: a.bytes.length, origin: "library", mime: a.mime, path: rel, provenance: { generator: "cyrus-library-use", ...a.provenance } });
      return { sha256, path: rel };
    },
  };
}
