import { StudioShell, useToast, type StudioMod } from "../studios/StudioShell";
import "./forge.css";

const KIND_LABEL: Record<string, string> = { model: "Models", "texture-set": "Texture sets", texture: "Textures", sprite: "Sprites", hdri: "HDRIs", decal: "Decals", sound: "Sounds", music: "Music", flipbook: "Flipbooks", "particle-texture": "Particles", "animation-clip": "Animation clips", "animated-model": "Animated models", "motion-preset": "Motion presets", "effect-preset": "Effect presets" };
const ALL_KINDS = Object.keys(KIND_LABEL);
const TIER_LABEL: Record<string, string> = { cc0: "CC0", "cc-by": "CC-BY", "proprietary-nxeon": "Nxeon library", "user-contributed": "Community" };
const NEEDS: Record<string, string> = { saka: "Saka+", all: "All models" };
const slotOf = (t: string) => (t.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").replace(/^([^a-z])/, "a_$1").slice(0, 32) || "asset").padEnd(2, "_");

export function LibraryBrowser({ mod, projectId, thumbs }: { mod: StudioMod; projectId: string | null; thumbs: boolean }) {
  const toast = useToast();
  const [q, setQ] = useState("");
  const [kind, setKind] = useState<string | null>(null);
  const [tier, setTier] = useState<string | null>(null);
  const [fit, setFit] = useState(true);
  const [offset, setOffset] = useState(0);
  const [res, setRes] = useState<BrowseResult | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [sel, setSel] = useState<BrowseRow | null>(null);
  const [img, setImg] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState(false);

  const search = useCallback(async () => {
    const u = new URLSearchParams({ q, fit: fit ? "1" : "0", offset: String(offset), game: "minecraft" });
    if (kind) u.set("kind", kind); if (tier) u.set("tier", tier);
    const r = await fetch(`/api/cyrus/library/v2/browse?${u}`, { cache: "no-store" });
    const b = await r.json().catch(() => ({}));
    if (!r.ok) { setErr(r.status === 404 ? "The asset library browser is not switched on." : String(b.error ?? "Could not search the library.")); return; }
    setErr(null); setRes(b as BrowseResult);
  }, [q, kind, tier, fit, offset]);
  useEffect(() => { const t = window.setTimeout(() => void search(), 250); return () => window.clearTimeout(t); }, [search]);
  useEffect(() => { // signed, viewer-scoped thumbnails (only when the backend serves files)
    if (!thumbs || !res) return;
    for (const r of res.rows.filter((x) => ["texture", "sprite", "decal", "flipbook", "particle-texture", "texture-set"].includes(x.kind) && !img[x.id]).slice(0, 24)) {
      fetch("/api/cyrus/library/v2/url", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ id: r.id, variant: "thumb@1" }) })
        .then((x) => (x.ok ? x.json() : null)).then((b) => { if (b?.url) setImg((m) => ({ ...m, [r.id]: b.url })); }).catch(() => undefined);
    }
  }, [res, thumbs]); // eslint-disable-line react-hooks/exhaustive-deps

  const use = async (r: BrowseRow) => {
    if (!projectId) return;
    setBusy(true);
    const x = await fetch("/api/cyrus/library/v2/use", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ ref: r.ref, projectId, slotId: slotOf(r.title) }) });
    const b = await x.json().catch(() => ({}));
    setBusy(false);
    toast(x.ok ? (b.reused ? `${r.title} is already in this mod` : `Added ${r.title} to this mod (slot ${slotOf(r.title)})`) : String(b.error ?? "Could not add it."), !x.ok);
  };
  const locked = new Map((res?.locked ?? []).map((l) => [l.kind, l.needs]));
  return (
    <StudioShell mod={mod} current="Asset library" studio={null} kind="library">
      <div className="fg-ws">
        <div className="fg-col">
          <section className="cys-panel cys-glass cys-hairline">
            <div className="cys-ph"><span className="cys-eyebrow">Search</span>{res ? <span className="cys-tag dim">{res.plan}</span> : null}</div>
            <div className="fg-body">
              <input className="fg-input" placeholder="wooden door, banshee wail, smoke puff…" value={q} onChange={(e) => { setQ(e.target.value); setOffset(0); }} aria-label="Search the library" />
              <label className="fg-ack"><input type="checkbox" checked={fit} onChange={(e) => { setFit(e.target.checked); setOffset(0); }} />Only what fits Minecraft</label>
              <div className="fg-field">Licence</div>
              <div className="fg-pills">
                <button type="button" className={`fg-pill ${tier === null ? "on" : ""}`} onClick={() => { setTier(null); setOffset(0); }}>Any</button>
                {Object.keys(TIER_LABEL).map((t) => { const ok = res ? res.tiers.includes(t as never) : true; return <button key={t} type="button" disabled={!ok} title={ok ? undefined : "Not on your plan"} className={`fg-pill ${tier === t ? "on" : ""}`} onClick={() => { setTier(t); setOffset(0); }}>{TIER_LABEL[t]}{ok ? "" : " 🔒"}</button>; })}
              </div>
            </div>
          </section>
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Kinds</span></div>
            <nav className="fg-tree" aria-label="Kinds">
              <button type="button" className={kind === null ? "on" : ""} onClick={() => { setKind(null); setOffset(0); }}>All kinds</button>
              {ALL_KINDS.map((k) => <button key={k} type="button" className={`${kind === k ? "on" : ""} ${locked.has(k) ? "bad" : ""}`} onClick={() => { setKind(k); setOffset(0); }} title={locked.has(k) ? `Needs ${NEEDS[locked.get(k) ?? ""] ?? "a higher plan"}` : undefined}>{KIND_LABEL[k]}{locked.has(k) ? ` · ${NEEDS[locked.get(k) ?? ""] ?? "locked"}` : ""}</button>)}
            </nav>
          </section>
        </div>

        <div className="fg-col">
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Results</span><span className="fg-mono">{res ? `${res.total.toLocaleString()} found` : "…"}</span></div>
            <div className="fg-body">
              {err ? <p className="fg-err">{err}</p> : null}
              {res?.notice ? <div className="fg-banner"><span>{res.notice}</span></div> : null}
              {res && !res.rows.length && !res.notice ? <p className="cys-hint">No match. Try other words for the situation, another kind, or turn off the Minecraft filter.</p> : null}
              <div className="fg-grid4">
                {res?.rows.map((r) => (
                  <button key={r.id} type="button" className={`fg-tile ${sel?.id === r.id ? "on" : ""}`} style={{ textAlign: "left" }} onClick={() => setSel(r)}>
                    <div style={{ height: 64, borderRadius: 8, background: "var(--well)", display: "grid", placeItems: "center", marginBottom: 6, overflow: "hidden" }}>
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      {img[r.id] ? <img src={img[r.id]} alt="" width={48} height={48} style={{ imageRendering: "pixelated" }} /> : <span className="fg-mono">{KIND_LABEL[r.kind]?.replace(/s$/, "") ?? r.kind}</span>}
                    </div>
                    <b style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.title}</b>
                    <span className="fg-mono">{TIER_LABEL[r.tier]} · q{r.quality}{r.variants > 1 ? ` · ${r.variants} variants` : ""}</span>
                  </button>
                ))}
              </div>
              {res && res.total > res.rows.length ? (
                <div className="fg-pills">
                  <button type="button" className="cys-btn sm" disabled={offset === 0} onClick={() => setOffset(Math.max(0, offset - 24))}>Previous</button>
                  <span className="fg-mono">{offset + 1}–{offset + res.rows.length}</span>
                  <button type="button" className="cys-btn sm" disabled={offset + res.rows.length >= res.total} onClick={() => setOffset(offset + 24)}>Next</button>
                </div>
              ) : null}
            </div>
          </section>
        </div>

        <div className="fg-col">
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Asset</span>{sel ? <span className="cys-tag dim">{sel.kind}</span> : null}</div>
            <div className="fg-body">
              {!sel ? <p className="cys-hint">Pick an asset to see its licence, fit and facts.</p> : (
                <>
                  <p className="fg-h1" style={{ fontSize: 15 }}>{sel.title}</p>
                  <p className="fg-sub">{sel.description}</p>
                  <dl className="fg-kv">
                    <dt>Licence</dt><dd>{TIER_LABEL[sel.tier]}{sel.spdx ? ` (${sel.spdx})` : ""}</dd>
                    {sel.attribution ? <><dt>Credit</dt><dd>{sel.attribution}</dd></> : null}
                    <dt>Quality</dt><dd>{sel.quality} / 100</dd>
                    {sel.tech.format ? <><dt>Format</dt><dd>{sel.tech.format}{sel.tech.width ? ` · ${sel.tech.width}px` : ""}{sel.tech.triangles != null ? ` · ${sel.tech.triangles} tris` : ""}{sel.tech.durationS != null ? ` · ${sel.tech.durationS.toFixed(1)} s` : ""}</dd></> : null}
                    <dt>Minecraft</dt><dd>{sel.fit ? sel.fit.fit : "not assessed"}</dd>
                    <dt>Ref</dt><dd>cat:{sel.id.slice(0, 12)}…</dd>
                  </dl>
                  {sel.fit?.reason ? <p className="cys-hint" style={{ margin: 0 }}>{sel.fit.reason}</p> : null}
                  <div className="fg-pills">{sel.tags.map((t) => <span key={t} className="fg-pill">{t}</span>)}</div>
                  <button type="button" className="cys-btn sm primary fg-edit" disabled={busy || !projectId || sel.fit?.fit === "no"} onClick={() => void use(sel)}>{sel.fit?.fit === "no" ? "Does not fit Minecraft" : busy ? "Adding…" : "Use in project"}</button>
                  <p className="cys-hint" style={{ margin: 0 }}>The mod keeps its own copy: it keeps building even if the asset later leaves the library.</p>
                </>
              )}
            </div>
          </section>
          <section className="cys-panel cys-glass">
            <div className="cys-ph"><span className="cys-eyebrow">Contributions</span></div>
            <div className="fg-body"><p className="cys-hint" style={{ margin: 0 }}>Textures you make from scratch in the Texture Studio join the community library automatically, after strict checks. Anything painted on a library or imported asset is never contributed.</p></div>
          </section>
          <p className="fg-ro cys-hint">Read-only on a phone: add assets from a larger screen.</p>
        </div>
      </div>
    </StudioShell>
  );
}

