import type { Metadata } from "next";
import { requireCyrusAdmin, cyrusAdminMetadata } from "@/lib/cyrus/admin/gate";
import { libraryFlags } from "@/lib/cyrus/library/backend/flags";
import { libraryAdminRead } from "@/lib/cyrus/library/backend/admin-read";
import { Badge, StatCard } from "@/components/ui/primitives";
import { Empty, Section, TableWrap, thCls } from "@/components/admin/cyrus/ui";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusAdminMetadata("Library hold queue");
}

/**
 * Cyrus r31: the owner's hold queue for AUTOMATIC library contributions (real-weapon, trademark, extremist, drugs,
 * mature violence, near-copies of removed assets, quality hard fails) + the takedown log. READ-ONLY: deciding a held
 * entry is not built here yet. Empty / "off" while CYRUS_LIBRARY_BACKEND is unset or its tables do not exist.
 */
export default async function LibraryHolds() {
  await requireCyrusAdmin("library");
  const on = libraryFlags().enabled;
  const v = on ? await libraryAdminRead({ limit: 100 }).catch((e: Error) => ({ error: e.message })) : null;
  if (!v || "error" in v) {
    return <Section title="Library hold queue"><Empty>{!on ? "The library backend is off (CYRUS_LIBRARY_BACKEND)." : `Could not read the library tables: ${(v as { error: string }).error.slice(0, 200)}`}</Empty></Section>;
  }
  return (
    <div className="space-y-6">
      <div className="grid gap-3 sm:grid-cols-4">
        <StatCard label="Entries" value={v.total.toLocaleString()} />
        <StatCard label="Held" value={String(v.byStatus.held ?? 0)} />
        <StatCard label="Open reports" value={String(v.openReports)} />
        <StatCard label="Mods using removed assets" value={String(v.dependentsOfRemoved)} />
      </div>
      <Section title={`Hold queue (${v.holdQueue.length})`}>
        {v.holdQueue.length === 0 ? <Empty>Nothing is waiting for review.</Empty> : (
          <TableWrap>
            <thead><tr><th className={thCls}>Asset</th><th className={thCls}>Kind</th><th className={thCls}>Why held</th><th className={thCls}>Flags</th><th className={thCls}>Reports</th><th className={thCls}>Contributor</th></tr></thead>
            <tbody>{v.holdQueue.map((h) => (
              <tr key={h.id} className="border-t border-white/5"><td className="px-3 py-2"><div className="font-medium">{h.title}</div><div className="font-mono text-[11px] opacity-60">{h.id.slice(0, 16)}</div></td><td className="px-3 py-2">{h.kind}</td><td className="px-3 py-2 text-sm">{h.reason ?? "-"}</td><td className="px-3 py-2">{h.flags.map((f) => <Badge key={f}>{f}</Badge>)}</td><td className="px-3 py-2">{h.reports}</td><td className="px-3 py-2 font-mono text-[11px]">{h.contributor ?? "library"}</td></tr>
            ))}</tbody>
          </TableWrap>
        )}
      </Section>
      <Section title="Takedown and moderation log">
        {v.takedownLog.length === 0 ? <Empty>No moderation actions yet.</Empty> : (
          <TableWrap>
            <thead><tr><th className={thCls}>When</th><th className={thCls}>Entry</th><th className={thCls}>Action</th><th className={thCls}>By</th><th className={thCls}>Reason</th><th className={thCls}>Dependents</th></tr></thead>
            <tbody>{v.takedownLog.map((l, i) => (
              <tr key={i} className="border-t border-white/5"><td className="px-3 py-2 text-xs">{new Date(l.at).toLocaleString()}</td><td className="px-3 py-2 font-mono text-[11px]">{l.entryId.slice(0, 16)}</td><td className="px-3 py-2">{l.action}{l.legal ? " (legal)" : ""}</td><td className="px-3 py-2 text-xs">{l.by}</td><td className="px-3 py-2 text-sm">{l.reason ?? "-"}</td><td className="px-3 py-2">{l.dependents}</td></tr>
            ))}</tbody>
          </TableWrap>
        )}
      </Section>
    </div>
  );
}
EOF
