// Cyrus r31: the studio library browser + "Use in project" (lib/cyrus/library/v2/browse.ts) and the contribution hook's
// switches (lib/cyrus/library/backend/studio-hook.ts). The plan gate is the build tools' own (access()); fails closed.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { createMemoryCatalogIndex } from "../lib/cyrus/library/v2/retrieval";
import { enrichStageA } from "../lib/cyrus/library/v2/stage-a";
import type { CatalogEntry } from "../lib/cyrus/library/v2/entry";
import { browseCatalog, handleBrowse, handleUse, type BrowseDeps } from "../lib/cyrus/library/v2/browse";
import { contributorIdOf, studioContributor } from "../lib/cyrus/library/backend/studio-hook";

const NOW = new Date("2026-10-11T00:00:00Z");
const sha = (b: Uint8Array | string) => createHash("sha256").update(b).digest("hex");
function entry(path: string, kind: string, format: string, tier = "cc0"): CatalogEntry {
  const b = Buffer.from(path);
  const r = enrichStageA({ id: sha(b), source: path.split("/")[0], pack: path.split("/")[1], path, kind, format, sizeBytes: b.length, tier, licenseSpdx: "CC0-1.0", licenseUrl: "https://example.org/l", licenceNote: null, retrievedAt: "2026-10-10", name: null },
    { profiles: [minecraftAssetProfile], now: NOW.toISOString() }, undefined, kind === "sound" ? { audio: { durationS: 1.2, sampleRate: 44100, channels: 1, bitDepth: 16, peakDb: -3, truePeakDb: -3, lufs: -18, silenceRatio: 0, dcOffset: 0, loopable: false, centroidHz: 2000, character: "transient", durationClass: "short", intensity: "loud", pitchBand: "mid" } } : { image: { width: 16, height: 16, hasAlpha: true } });
  assert.ok(r.entry, JSON.stringify(r.errors));
  return { ...r.entry!, status: "published", statusReason: null, flags: [] };
}
async function index() {
  const ix = createMemoryCatalogIndex();
  await ix.upsert([entry("kenney/doors/door_wooden.png", "texture", "png"), entry("kenney/sfx/door_creak.ogg", "sound", "ogg"), entry("pvfx/smoke/smoke_puff.png", "flipbook", "png")]);
  return ix;
}
function deps(o: Partial<BrowseDeps> = {}): BrowseDeps {
  let ix: Awaited<ReturnType<typeof index>> | null = null;
  return { on: () => true, viewer: async () => ({ userId: "u1" }), planOf: async () => "all", index: async () => (ix ??= await index()), proprietaryCleared: false, ownsProject: async (u, p) => u === "u1" && p === "cp" + "1".repeat(20), rateLimit: () => ({ ok: true }), ...o };
}
const get = (d: BrowseDeps, qs = "") => handleBrowse(new Request(`http://x/api/cyrus/library/v2/browse?${qs}`), d);
const post = (d: BrowseDeps, body: unknown) => handleUse(new Request("http://x/u", { method: "POST", body: JSON.stringify(body), headers: { "content-type": "application/json" } }), d);
const REF = () => `cat:${sha(Buffer.from("kenney/doors/door_wooden.png"))}`;

describe("r31 library browser", () => {
  it("the top plan sees every kind incl. motion; a search and a kind filter narrow it; only published rows", async () => {
    const r = await browseCatalog({ text: "", game: "minecraft" }, { index: await index(), plan: "all", proprietaryCleared: false });
    assert.equal(r.notice, null); assert.equal(r.locked.length, 0);
    assert.ok(r.kinds.includes("flipbook") && r.kinds.includes("effect-preset"));
    assert.equal(r.total, 3);
    const f = await browseCatalog({ kind: "flipbook", game: "minecraft" }, { index: await index(), plan: "all", proprietaryCleared: false });
    assert.deepEqual(f.rows.map((x) => x.kind), ["flipbook"]);
    assert.match(f.rows[0].ref, /^cat:[0-9a-f]{64}$/);
  });
  it("the plan gate is the build tools' own: Saka gets sounds only, visuals locked with what unlocks them; free gets nothing; unknown fails closed", async () => {
    const saka = await browseCatalog({}, { index: await index(), plan: "saka", proprietaryCleared: false });
    assert.deepEqual([...new Set(saka.rows.map((x) => x.kind))], ["sound"]);
    assert.equal(saka.locked.find((l) => l.kind === "texture")?.needs, "all");
    const asked = await browseCatalog({ kind: "texture" }, { index: await index(), plan: "saka", proprietaryCleared: false });
    assert.equal(asked.rows.length, 0); assert.match(asked.notice!, /locked/);
    assert.equal((await browseCatalog({}, { index: await index(), plan: "free", proprietaryCleared: false })).rows.length, 0);
    const unk = await browseCatalog({}, { index: await index(), plan: "mystery", proprietaryCleared: false });
    assert.equal(unk.rows.length, 0); assert.match(unk.notice!, /could not be checked/);
    assert.ok(!saka.tiers.includes("proprietary-nxeon"), "the proprietary library needs the owner's clearance");
  });
  it("HTTP: off / no viewer = 404, no index = 503, rate limit 429", async () => {
    assert.equal((await get(deps({ on: () => false }))).status, 404);
    assert.equal((await get(deps({ viewer: async () => null }))).status, 404);
    assert.equal((await get(deps({ index: async () => null }))).status, 503);
    assert.equal((await get(deps({ rateLimit: () => ({ ok: false, retryAfterSec: 2 }) }))).status, 429);
    const ok = await (await get(deps(), "q=door&fit=0")).json();
    assert.ok(ok.rows.length >= 1);
  });
  it("Use in project: own project only, 503 until the backend is wired, the server's plan goes to the use function", async () => {
    const pid = "cp" + "1".repeat(20);
    assert.equal((await post(deps(), { ref: REF(), projectId: pid, slotId: "door" })).status, 503);
    assert.equal((await post(deps(), { ref: REF(), projectId: "cp" + "2".repeat(20), slotId: "door" })).status, 404);
    assert.equal((await post(deps(), { ref: "cat:nope", projectId: pid, slotId: "door" })).status, 400);
    const seen: unknown[] = [];
    const d = deps({ planOf: async () => "saka", use: async (r) => { seen.push(r.plan); return r.ref === REF() ? { ok: false, code: "asset_locked", reason: "textures need All models" } : { ok: true, slot: {}, copied: true, reused: false, rule: null }; } });
    assert.equal((await post(d, { ref: REF(), projectId: pid, slotId: "door" })).status, 403);
    assert.deepEqual(seen, ["saka"]);
  });
  it("contribution hook: off without the switches and a secret; the contributor id is opaque and stable", () => {
    assert.equal(studioContributor({}), undefined);
    assert.equal(studioContributor({ CYRUS_LIBRARY_BACKEND: "1", CYRUS_LIBRARY_CONTRIBUTE: "1" }), undefined, "no URL secret: off");
    const id = contributorIdOf("s".repeat(32), "usr_1");
    assert.match(id, /^[a-z0-9_-]{4,64}$/); assert.ok(!id.includes("usr_1"));
    assert.equal(id, contributorIdOf("s".repeat(32), "usr_1"));
  });
});
EOF
timeout 900 /opt/nxeon/scripts/devhost test test/cyrus-library-browse.test.ts test/cyrus-studios.test.ts 2>&1 | grep -E "^# (pass|fail)|not ok|rror|expected|actual" | head -20

